// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Gözlem, anket, görüşme ve örnekleme yöntemleri (senaryolarla) (orta).
const ozResearch3Orta = <(String, String, List<String>, String)>[
  ('Aşağıdaki araştırma sorularından hangisi tek başına gözlemle yanıtlanmaya en az uygundur?', 'Öğrenciler okul yemeklerinin tadı hakkında ne düşünüyor?', ['Öğrenciler teneffüste en çok hangi oyunları oynuyor?', 'Kantinde sıra bekleme süresi ortalama kaç dakika?', 'Kütüphanede en çok hangi masalar dolu oluyor?'], 'Düşünce ve görüşler doğrudan görülemez; bunları öğrenmek için kişilere sormak gerekir. Diğer seçenekler gözlenebilir davranışlardır.'),
  ('Katılımlı gözlem yapan bir araştırmacının zamanla grubun bakış açısını benimseyip eleştirel mesafesini kaybetmesine ne ad verilir?', 'Yerlileşme', ['Hawthorne etkisi', 'Halo etkisi', 'Kapsam hatası'], 'Yerlileşme (going native), gözlemcinin incelediği gruba fazlasıyla özdeşleşerek nesnelliğini yitirmesidir.'),
  ('Katılımsız gözlemin katılımlı gözleme göre bir sınırlılığı aşağıdakilerden hangisidir?', 'Davranışların altındaki anlamları kavramanın güçleşmesi', ['Gözlemcinin gruba aşırı özdeşleşme riskinin artması', 'Gözlemcinin gruba kabul edilmesinin uzun sürmesi', 'Araştırmacının grubun etkinliklerine katılmak zorunda kalması'], 'Dışarıdan bakan gözlemci davranışı görür ama katılımcıların ona yüklediği anlamı her zaman çözemez. Diğer seçenekler katılımlı gözlemin sorunlarıdır.'),
  ('Gold\'un sınıflamasında, grupla hiçbir etkileşime girmeden yalnızca dışarıdan izleyen gözlemcinin rolü hangisidir?', 'Tam gözlemci', ['Tam katılımcı', 'Katılımcı olarak gözlemci', 'Gözlemci olarak katılımcı'], 'Tam gözlemci, grubun etkinliklerine katılmaz ve onlarla etkileşime girmez; örneğin tek yönlü aynanın arkasından izler.'),
  ('Bir araştırmacı bir fabrikada işçi olarak işe girip araştırma yaptığını kimseye söylemeden çalışma koşullarını kaydediyor. Bu yaklaşımın en önemli etik sorunu nedir?', 'Katılımcıların bilgilendirilmiş onamının alınmaması', ['Örneklemin tek bir fabrikayla sınırlı kalıp küçük olması', 'Verilerin sayısal olmaması', 'Gözlem süresinin fazla uzun olması'], 'Gizli gözlemde katılımcılar incelendiklerini bilmez ve onam veremez; bu, araştırma etiğinin temel ilkelerinden biriyle çatışır.'),
  ('Gizli gözlemin açık gözleme göre metodolojik avantajı aşağıdakilerden hangisidir?', 'Katılımcıların izlendiklerini bilerek davranış değiştirmesini önlemesi', ['Etik kurul onayına gerek bırakmaması', 'Gözlemcinin not almasını kolaylaştırması', 'Grup üyelerinin araştırmacıya daha çok ve daha açık bilgi vermesi'], 'İnsanlar izlendiklerini bilmediklerinde doğal davrandıkları için gözlemci etkisi azalır. Ancak gizli gözlem yine de etik değerlendirme gerektirir.'),
  ('Kamuya açık bir parkta insanların bankları nasıl kullandığını, kimliklerini kaydetmeden izlemek neden çoğu etik çerçevede gizli gözlemin daha kabul edilebilir bir biçimi sayılır?', 'Kişiler kamusal alanda zaten görülebilir davranmakta ve kimlikleri kaydedilmemektedir', ['Parkta gözlem yapmak için hiçbir kural bulunmaz', 'Kamusal alanda insanların davranışları her zaman yapay ve önceden planlıdır', 'Park kullanıcıları araştırma sonuçlarından etkilenmez'], 'Kamusal alanda kimliksiz gözlem, kişilerin mahremiyet beklentisinin düşük olduğu bir ortamda yapılır ve bireylere zarar riski azdır.'),
  ('Bir araştırmacı yeni açılan bir mahalle pazarını hiçbir hazır kategori kullanmadan, gördüğü her şeyi ayrıntılı notlara dökerek inceliyor. Bu yaklaşım en çok hangi aşamada yararlıdır?', 'Konu hakkında az bilgi bulunan keşif aşamasında', ['Hipotezlerin kesin olarak sınandığı son aşamada', 'Büyük örneklemlerden oran hesaplanan aşamada', 'Önceden belirlenmiş davranışların sayıldığı aşamada'], 'Yapılandırılmamış gözlem, neyin önemli olduğunun henüz bilinmediği keşif aşamasında yeni kategorilerin ortaya çıkmasını sağlar.'),
  ('Alan notlarında \'betimleyici notlar\' ile \'yansıtıcı notlar\' arasındaki ayrım neyi amaçlar?', 'Görülen olayları araştırmacının yorumlarından ayırmayı', ['Sabah ve akşam yapılan gözlemleri ayırmayı', 'Erkek ve kadın katılımcıları ayırmayı', 'Sayısal verileri grafiklere dönüştürmeyi'], 'Betimleyici notlar ne olduğunu, yansıtıcı notlar ise araştırmacının düşünce ve yorumlarını içerir; bu ayrım gözlem ile yorumun karışmasını önler.'),
  ('Aşağıdaki alan notu cümlelerinden hangisi betimleyici (yorumsuz) bir gözlem kaydıdır?', 'Kadın müşteri satıcıya iki kez fiyat sordu ve ürünü rafa geri koydu.', ['Kadın müşteri ürünü pahalı bulduğu için sinirlendi.', 'Satıcı müşteriye karşı açıkça kabaydı.', 'Müşteri aslında ürünü hiç istememişti.'], 'Yalnızca ilk cümle görülen davranışı aktarır; diğerleri duygular veya niyetler hakkında gözlemcinin çıkarımlarını içerir.'),
  ('Bir araştırmacı ormanda şempanzelerin alet kullanımını yıllarca izliyor. Bu çalışmanın kontrollü ortam gözlemine göre zayıf yanı hangisidir?', 'İlgilenilen davranışın ne zaman görüleceğinin denetlenememesi', ['Davranışların yapay koşullarda ortaya çıkması', 'Hayvanların doğal davranışlarının bozulması', 'Bulguların gerçek yaşama aktarılamaması'], 'Doğal ortamda araştırmacı olayları başlatamaz; beklenen davranışın ortaya çıkması için uzun süre beklemek gerekebilir.'),
  ('Hawthorne etkisi adını hangi çalışmalardan almıştır?', 'Bir elektrik fabrikasında 1920\'lerde yapılan verimlilik çalışmalarından', ['Bir hastanede yapılan ilaç denemelerinden', 'Bir okulda yapılan ilk zekâ testi uygulamalarının sonuçlarından', 'Bir seçim öncesi yapılan kamuoyu yoklamasından'], 'Ad, Western Electric şirketinin Chicago yakınlarındaki Hawthorne tesislerinde yürütülen işçi verimliliği çalışmalarından gelir.'),
  ('Bir gözlemcinin bir öğrenciyi önceden \'başarılı\' olarak tanıdığı için onun belirsiz davranışlarını da olumlu kaydetmesine ne ad verilir?', 'Hale (halo) etkisi', ['Hawthorne etkisi', 'Yerlileşme', 'Kapsam hatası'], 'Hale etkisi, bir kişi hakkındaki genel izlenimin onun diğer özelliklerinin değerlendirilmesini de etkilemesidir.'),
  ('Bir araştırmacı bir anaokulunda her çocuğu sırayla 30 saniye izleyip o anda ne yaptığını kaydediyor ve bunu gün boyunca tekrarlıyor. Bu kayıt yöntemi hangisidir?', 'Zaman örneklemesi', ['Olay örneklemesi', 'Anekdot kaydı', 'Kartopu örneklemesi'], 'Zaman örneklemesinde gözlem belirli ve düzenli zaman aralıklarında yapılır; davranış o aralıkta görülüp görülmediğine göre kaydedilir.'),
  ('Derecelendirme ölçeğini kontrol listesinden ayıran temel özellik nedir?', 'Davranışın görülüp görülmediğinin yanında ne düzeyde görüldüğünü de kaydetmesi', ['Yalnızca nitel betimlemeler içermesi ve hiçbir puan kullanmaması', 'Hiçbir ön hazırlık gerektirmemesi', 'Yalnızca kendi kendini değerlendirmede kullanılması'], 'Derecelendirme ölçeğinde gözlemci davranışın niteliğini veya sıklığını (ör. 1–5 arası) puanlar; kontrol listesi yalnızca var-yok bilgisi verir.'),
  ('İki gözlemci aynı 40 davranış aralığını bağımsız olarak kodluyor ve 34 aralıkta aynı kodu veriyor. Basit uyum yüzdesi kaçtır?', '%85', ['%80', '%34', '%90'], 'Uyum yüzdesi = aynı kodlanan aralık / toplam aralık × 100 = 34/40 × 100 = %85.'),
  ('Gözlemciler arası uyumun düşük çıkması öncelikle neye işaret eder?', 'Kodlama kategorilerinin ya da gözlemci eğitiminin yetersiz olabileceğine', ['Gözlenen kişilerin davranışlarının gözlem boyunca hiç değişmediğine', 'Örneklemin evreni tam olarak temsil ettiğine', 'Gözlem süresinin gereğinden uzun tutulduğuna'], 'Aynı davranışı farklı kodlayan gözlemciler, kategorilerin belirsiz tanımlandığını veya gözlemcilerin yeterince eğitilmediğini gösterir.'),
  ('İki gözlemcinin gözlem öncesinde aynı video kayıtlarını birlikte kodlayıp farklılıkları tartışması hangi amaca hizmet eder?', 'Kodlama kategorilerinin ortak biçimde anlaşılmasına', ['Gözlem süresinin uzatılmasına', 'Katılımcı sayısının artırılmasına', 'Gözlemci etkisinin ortadan kalkmasına'], 'Deneme kodlamaları ve tartışmalar gözlemci eğitiminin bir parçasıdır ve kategorilerin herkes tarafından aynı biçimde uygulanmasını sağlar.'),
  ('Etnografik bir çalışmada araştırmacının topluluğa girişini kolaylaştıran ve onu diğer üyelerle tanıştıran kişiye ne ad verilir?', 'Kilit bilgi verici', ['Görüşmeci', 'Örneklem çerçevesi', 'Kodlayıcı'], 'Kilit bilgi verici (anahtar kişi), topluluğu iyi tanıyan ve araştırmacıya hem bilgi hem de erişim sağlayan kişidir.'),
  ('Etnografik çalışmalara yöneltilen en yaygın eleştiri aşağıdakilerden hangisidir?', 'Bulguların başka gruplara genellenmesinin zor olması', ['Verilerin tamamen sayısal olması', 'Araştırmacının grupla hiç temas kurmadan dışarıdan çalışması', 'Çok kısa sürede tamamlanması'], 'Etnografi genellikle tek bir topluluğu derinlemesine inceler; bu derinlik genelleme gücünü sınırlar.'),
  ('Bir gözlemcinin oturduğu yer nedeniyle sınıfın yalnızca ön sıralarını görebilmesi, gözlem verisinde hangi soruna yol açar?', 'Kaydedilen davranışların tüm sınıfı temsil etmemesine', ['Gözlemciler arası uyumun kendiliğinden artmasına', 'Hawthorne etkisinin ortadan kalkmasına', 'Davranışların daha nesnel kaydedilmesine'], 'Gözlemcinin görüş alanı sınırlıysa veri yalnızca görülen kısmı yansıtır; bu da gözlenen birimlerin seçiminde sistematik bir eksiklik yaratır.'),
  ('Hastane bekleme salonunda hastaların bekleme süresini ölçen bir araştırmacının, yalnızca sırası gelenlerin süresini kaydedip beklemekten vazgeçip gidenleri hesaba katmaması ne tür bir eksikliktir?', 'Gözlem kapsamının bir alt grubu dışarıda bırakması', ['Gözlemciler arası uyumsuzluk', 'Hawthorne etkisi', 'Merkezî eğilim hatası'], 'Vazgeçip gidenler büyük olasılıkla en uzun bekleyenlerdir; onları dışarıda bırakmak bekleme süresini olduğundan kısa gösterir.'),
  ('Anketlerin görüşmelere göre başlıca sınırlılığı aşağıdakilerden hangisidir?', 'Yanıtların nedenlerini derinleştirmeye pek olanak vermemesi', ['Çok sayıda kişiye ulaşmanın imkânsız ve çok pahalı olması', 'Verilerin sayısal biçimde özetlenmesinin hiç mümkün olmaması', 'Herkese aynı soruların sorulmasının teknik olarak engellenmesi'], 'Anket standart sorularla geniş bir kitleye ulaşır, ancak görüşmedeki gibi \'neden?\' diye sorup yanıtı derinleştirmek zordur.'),
  ('Açık uçlu soruların çok sayıda katılımcıya uygulandığı bir ankette araştırmacıyı en çok zorlayan aşama hangisi olur?', 'Yanıtların kategorilere ayrılıp kodlanması', ['Soruların kâğıda basılması', 'Katılımcılara anketin dağıtılması', 'Anketin başlığının ve giriş yazısının belirlenmesi'], 'Serbest metin yanıtlarını okuyup ortak kategoriler altında toplamak zaman alır ve kodlayıcı yargısı gerektirir.'),
  ('Bir ölçekte \'soğuk–sıcak\', \'yavaş–hızlı\' gibi zıt sıfat çiftlerinin iki ucunda yer aldığı ve katılımcının aradaki basamaklardan birini işaretlediği ölçek türü hangisidir?', 'Anlamsal farklılık ölçeği', ['Likert tipi derecelendirme ölçeği', 'Kontrol listesi', 'Sıralama ölçeği'], 'Osgood\'un geliştirdiği anlamsal farklılık ölçeğinde bir kavram, zıt sıfat çiftleri arasında derecelendirilir.'),
  ('Bir tutum ölçeğindeki bazı maddelerin olumsuz yönde yazılması (ör. \'Okul bana sıkıcı gelir\') hangi eğilimi fark etmeye yardımcı olur?', 'Maddeleri okumadan hep aynı seçeneği işaretleme eğilimini', ['Katılımcıların cinsiyetlerini yanlış ya da eksik belirtmelerini', 'Anketin yazım ve noktalama hatalarını', 'Örneklem büyüklüğünün yetersiz kalmasını'], 'Ters kodlanan maddeler, her maddeye otomatik olarak \'katılıyorum\' diyen (onaylama eğilimi gösteren) katılımcıların fark edilmesini sağlar.'),
  ('Aşağıdaki sorulardan hangisi yönlendirici olmayan, tarafsız bir biçimde yazılmıştır?', 'Okul üniformasına ilişkin görüşünüz hangisine daha yakındır?', ['Çoğu veli gibi siz de üniformayı gereksiz buluyor musunuz?', 'Öğrencileri tek tipleştiren üniformayı destekliyor musunuz?', 'Üniformanın getirdiği düzenin ve disiplinin farkında mısınız?'], 'Tarafsız soru bir görüşü önceden önermez; diğer seçenekler çoğunluğa uyma baskısı, olumsuz niteleme veya olumlu varsayım içerir.'),
  ('\'Uzmanların çoğu düzenli kitap okumanın faydalı olduğunu söylüyor. Siz ne sıklıkla kitap okursunuz?\' sorusu hangi tür bir etki yaratabilir?', 'Katılımcının okuma sıklığını olduğundan fazla bildirmesine yol açabilir', ['Katılımcının soruyu hiç anlamamasına ve boş bırakmasına yol açabilir', 'Katılımcının yaşını ve eğitim düzeyini yanlış ya da eksik biçimde yazmasına neden olabilir', 'Örneklem çerçevesinin dışında kalan kişilerin sayısını artırabilir'], 'Sorudan önce verilen \'uzmanlar\' bilgisi bir norm oluşturur; katılımcı kendini olumlu göstermek için okuma sıklığını abartabilir.'),
  ('\'Sigarayı bıraktığınızdan beri kendinizi daha iyi hissediyor musunuz?\' sorusu, hiç sigara içmemiş biri için neden sorunludur?', 'Soru, katılımcı hakkında doğru olmayabilecek bir varsayım içermektedir', ['Soru iki ayrı seçenek sunduğu için anlaşılmaz hâle gelmektedir', 'Soru kapalı uçlu olduğu için verilen yanıtlar hiçbir biçimde kodlanamamaktadır', 'Soru Likert ölçeğiyle sorulmadığı için tümüyle geçersiz sayılmaktadır'], 'Soru, katılımcının daha önce sigara içtiğini ve bıraktığını varsayar; bu varsayımı karşılamayanlar uygun bir yanıt bulamaz.'),
  ('Duygusal çağrışımı güçlü sözcüklerle (\'israf\', \'katliam\', \'kahraman\' gibi) kurulan anket sorularına ne ad verilir?', 'Yüklü soru', ['Açık uçlu soru', 'Filtre soru', 'Demografik soru'], 'Yüklü sorular, duygusal yükü olan sözcükler aracılığıyla katılımcının yanıtını etkiler.'),
  ('Aşağıdaki anket sorularından hangisi çift namlulu değildir?', 'Öğretmeninizin ders anlatımını ne kadar anlaşılır buluyorsunuz?', ['Öğretmeniniz dakik ve güler yüzlü müdür?', 'Kütüphane sessiz ve iyi aydınlatılmış mıdır?', 'Servis şoförü güvenli ve hızlı araç kullanır mı?'], 'Yalnızca ilk soru tek bir özelliği sorar; diğerlerinde birbirinden bağımsız iki özellik bir arada sorulmaktadır.'),
  ('Bir ankette \'Düzenli olarak spor yapar mısınız?\' sorusunun en önemli zayıflığı nedir?', '\'Düzenli\' sözcüğünün kişiden kişiye farklı anlaşılması', ['Sorunun yalnızca iki yanıt seçeneğiyle sorulabilecek olması', 'Sorunun çok uzun ve karmaşık olduğu', 'Sorunun açık uçlu biçimde sorulduğu'], 'Kimi haftada bir kez, kimi her gün spor yapmayı \'düzenli\' sayabilir; \'haftada kaç gün\' gibi somut bir ifade belirsizliği giderir.'),
  ('Genel halka uygulanacak bir ankette \'Hanenizin harcanabilir gelirindeki reel değişimi nasıl değerlendirirsiniz?\' sorusunun temel sorunu nedir?', 'Teknik terimler nedeniyle pek çok katılımcı soruyu anlamayabilir', ['Soru katılımcıları belirli bir yanıta yönlendirecek biçimde kurulmuştur', 'Soru aynı anda birbirinden bağımsız iki ayrı konuyu birlikte sormaktadır', 'Soru katılımcının hiç yaşamadığı bir durumu varsaymaktadır'], 'Anket dili hedef kitlenin anlayacağı sadelikte olmalıdır; \'harcanabilir gelir\' ve \'reel değişim\' gibi terimler çoğu kişiye yabancıdır.'),
  ('\'Okulda cep telefonunun yasaklanmaması gerektiğini düşünmüyor musunuz?\' sorusundaki temel sorun nedir?', 'Birden fazla olumsuz ifade sorunun anlaşılmasını güçleştirmektedir', ['Soru herhangi bir yanıt seçeneği içermemektedir', 'Soru gereğinden fazla demografik bilgi istemektedir', 'Soru yalnızca bir konuyu sorduğu için yetersizdir'], 'Çifte olumsuzluk (\'yasaklanmaması\' ve \'düşünmüyor musunuz\') katılımcının \'evet\' ya da \'hayır\' yanıtının ne anlama geldiğini karıştırmasına yol açar.'),
  ('\'Günde kaç saat televizyon izlersiniz? (a) 1–2 saat (b) 3–4 saat (c) 5–6 saat\' sorusundaki temel eksiklik nedir?', 'Hiç izlemeyenler ve 6 saatten fazla izleyenler için seçenek yoktur', ['Seçenekler birbiriyle çakıştığı için bazı kişiler iki seçeneğe birden uyar', 'Soru katılımcının izlediği programın içeriği hakkında bilgi vermektedir', 'Soru iki ayrı konuyu tek bir cümlede birleştirerek sormaktadır'], 'Seçenekler kapsayıcı (tüm olası yanıtları içeren) olmalıdır; 0 saat ve 6 saatin üzeri dışarıda kalmıştır.'),
  ('Bir anket memnuniyet sorusu için \'Çok memnunum\', \'Memnunum\', \'Biraz memnunum\', \'Memnun değilim\' seçeneklerini kullanıyor. Bu seçenek takımının sorunu nedir?', 'Olumlu ve olumsuz seçenekler dengesizdir', ['Seçenekler birbiriyle tamamen çakışır ve örtüşür', 'Seçenekler açık uçlu bir soruya aittir', 'Seçenek sayısı ikiden azdır'], 'Üç olumlu karşısında yalnızca bir olumsuz seçenek bulunması yanıtları olumlu yöne kaydırabilir; ölçek simetrik olmalıdır.'),
  ('Bir ankette tüm katılımcılara sorulan \'Hangi tür müzik dinlersiniz?\' sorusunda yalnızca tek seçenek işaretlenmesine izin veriliyor. Bu düzenlemenin olası sorunu nedir?', 'Birden çok türü dinleyenlerin yanıtı eksik kalır', ['Seçenekler kendiliğinden karşılıklı dışlayıcı ve kapsayıcı hâle gelir', 'Sorunun yanıtları sayısal biçimde hiçbir şekilde özetlenemez', 'Katılımcıların yaşları ve cinsiyetleri yanıtlardan anlaşılamaz'], 'Pek çok kişi birden fazla türü dinler; tek seçim zorunluluğu verinin gerçeği tam yansıtmamasına yol açar. \'Birden çok seçebilirsiniz\' talimatı uygun olur.'),
  ('Bir ankette \'Ülkedeki genel ekonomik durumu nasıl değerlendiriyorsunuz?\' sorusu, \'Kendi ekonomik durumunuzu nasıl değerlendiriyorsunuz?\' sorusundan önce sorulduğunda yanıtların değişebilmesi neyin örneğidir?', 'Soru sırası etkisi', ['Kapsam hatası', 'Kartopu etkisi', 'Rastgele örnekleme hatası'], 'Önceki soru, sonraki soruya yanıt verilirken akla gelen bağlamı değiştirir; bu soru sırası (bağlam) etkisidir.'),
  ('Anket tasarımında hassas ya da kişisel soruların (gelir, sağlık gibi) genellikle anketin sonuna yakın yerleştirilmesinin nedeni nedir?', 'Katılımcı ankete ısınmadan bu sorularla karşılaşıp anketi bırakmasın diye', ['Bu soruların yanıtları en az önemli veriler olduğu ve sıklıkla atlandığı için', 'Anketin sonundaki sorular kodlama sırasında daha kolay işlendiği için', 'Hassas soruların başta sorulması kesin olarak yasal düzenlemelerle yasaklandığı için'], 'Anketin başında hassas sorular katılımcının güvenini sarsabilir ve bırakma oranını artırabilir; güven oluştuktan sonra sorulmaları daha uygundur.'),
  ('Seçenek sırasının yanıtları etkilemesini önlemek için çevrimiçi anketlerde sıklıkla uygulanan önlem nedir?', 'Seçenek sırasını her katılımcı için rastgele değiştirmek', ['Seçenekleri her zaman alfabetik sıraya dizip sabit tutmak', 'Seçenek sayısını her soruda en fazla ikiyle sınırlandırmak', 'Seçenekleri gizleyip yalnızca açık uçlu yanıt istemek'], 'Rastgele sıralama, sıra etkisinin tüm seçeneklere eşit dağılmasını sağlar ve sistematik bir kaymayı önler.'),
  ('Pilot uygulamada katılımcıların çoğunun aynı soruyu boş bıraktığı görülürse araştırmacı öncelikle ne yapmalıdır?', 'Sorunun anlaşılırlığını ve uygunluğunu yeniden gözden geçirmelidir', ['Soruyu olduğu gibi bırakıp örneklemi büyütmeli ve uygulamaya devam etmelidir', 'Boş bırakan katılımcıları sonraki tüm çözümlemelerin dışında tutmalıdır', 'Soruyu zorunlu yapıp yanıtsız bırakılmasını tamamen engellemelidir'], 'Toplu boş bırakma, sorunun anlaşılmadığını, hassas olduğunu ya da uygun seçenek içermediğini düşündürür; pilot uygulamanın amacı tam olarak bunu yakalamaktır.'),
  ('Pilot uygulama yapılan katılımcıların asıl örnekleme genellikle dahil edilmemesinin nedeni nedir?', 'Anketin önceki sürümünü görmüş olmaları yanıtlarını etkileyebilir', ['Bu kişiler genellikle araştırma ekibinin üyeleri ve yakınları olduğu için', 'Pilot katılımcıların yanıtları hukuken asla kullanılamayacağı için', 'Pilot uygulamada hiçbir zaman veri kaydı yapılmadığı için'], 'Pilot katılımcılar soruları önceden görmüş ve belki tartışmıştır; bu ön deneyim asıl uygulamadaki yanıtlarını farklılaştırabilir.'),
  ('Yaşlı nüfusun görüşlerini öğrenmek isteyen bir araştırmacının yalnızca çevrimiçi anket kullanması hangi soruna yol açabilir?', 'İnternet kullanmayan yaşlıların örneklem dışında kalmasına', ['Yanıtların çok yavaş biçimde ve aylar içinde toplanmasına', 'Anketör etkisinin artarak yanıtların değişmesine', 'Soruların her katılımcıya farklı ifadelerle sorulmasına'], 'Yaşlılar arasında internet kullanımı daha düşük olabildiğinden yalnızca çevrimiçi yöntem bu grubun bir kısmını sistematik olarak dışarıda bırakır.'),
  ('Düşük yanıt oranının asıl tehlikesi aşağıdakilerden hangisidir?', 'Yanıt verenlerin yanıt vermeyenlerden sistematik biçimde farklı olabilmesi', ['Toplanan verilerin bilgisayara girilmesinin daha uzun sürmesi', 'Anketin soru sayısının kendiliğinden ve fark edilmeden azalması', 'Katılımcıların sorulara her zaman olumsuz yanıt vermesi'], 'Yalnızca konuyla çok ilgilenenler ya da belirli özelliktekiler yanıt verirse sonuçlar evreni yansıtmaz; bu yanıtsızlık hatasıdır.'),
  ('Bir öğrenci kulübünün memnuniyet anketine yalnızca kulübe çok bağlı üyelerin yanıt verdiği düşünülüyor. Bu durum sonuçları en olası biçimde nasıl etkiler?', 'Memnuniyet olduğundan yüksek görünür', ['Memnuniyet gerçekte olduğundan düşük görünür', 'Sonuçlar hiçbir yönde etkilenmez', 'Yalnızca yanıt sayısı artar'], 'Bağlılığı yüksek üyeler büyük olasılıkla daha memnundur; yanıtsız kalan daha az bağlı üyeler eksik kaldığı için ortalama yukarı kayar.'),
  ('Bir araştırmacı ankete yanıt vermeyenlerden küçük bir grubu ayrıca telefonla arayıp kısa sorular soruyor. Bu uygulamanın amacı nedir?', 'Yanıt verenlerle vermeyenlerin farklı olup olmadığını anlamak', ['Yanıt vermeyenleri ankete katılmadıkları için uyarmak', 'Anketin toplam maliyetini mümkün olduğunca düşürmek', 'Örneklem çerçevesini tamamen değiştirmek'], 'Yanıtsızlık takip çalışması, yanıtsız kalan grubun özelliklerini öğrenerek sonuçlarda yanıtsızlık kaynaklı bir sapma olup olmadığını değerlendirmeyi sağlar.'),
  ('Bir kurum her yıl \'o yıl 18 yaşında olan gençlere\' aynı soruları, ama her yıl farklı bir örnekleme soruyor. Bu tasarım hangisidir?', 'Trend anketi', ['Panel anketi', 'Kohort anketi', 'Vaka çalışması'], 'Trend anketinde aynı evren (her yılın 18 yaşındakileri) farklı zamanlarda farklı örneklemlerle incelenir; aynı kişiler izlenmez.'),
  ('Ulusal bir sağlık araştırmasında 300 görüşmeci binlerce haneyle görüşecektir. Yapılandırılmış görüşmenin bu durumda tercih edilmesinin temel nedeni nedir?', 'Farklı görüşmecilerden gelen verilerin karşılaştırılabilir olması', ['Her görüşmecinin istediği soruyu kendi sözcükleriyle sorabilmesi', 'Katılımcıların kendi yaşam öykülerini ayrıntılı ve uzun anlatabilmesi', 'Görüşmelerin hiçbir soru formu hazırlanmadan yapılabilmesi'], 'Çok sayıda görüşmecinin olduğu çalışmalarda standart sorular, görüşmeciden kaynaklanan farklılığı azaltır ve verileri birleştirilebilir kılar.'),
  ('Yapılandırılmış görüşmenin en önemli sınırlılığı aşağıdakilerden hangisidir?', 'Beklenmedik ama önemli konuların araştırılmasına esneklik tanımaması', ['Görüşmeciler arasında hiçbir standart ve ortak sorunun bulunmaması', 'Elde edilen verilerin sayısallaştırılmasının neredeyse imkânsız olması', 'Görüşmecilerin eğitilmesini ve hazırlanmasını hiç gerektirmemesi'], 'Sorular sabit olduğundan görüşmeci katılımcının açtığı yeni ve önemli bir konuyu izleyemez.'),
  ('Yarı yapılandırılmış görüşmede kullanılan \'görüşme formu\' en doğru biçimde nasıl tanımlanır?', 'Ana soruları ve olası ek soruları içeren esnek bir rehber', ['Görüşmecinin kelimesi kelimesine okuması gereken ve değiştiremeyeceği metin', 'Katılımcının görüşmeden önce yazılı olarak doldurup teslim ettiği anket', 'Görüşme sonrasında yalnızca katılımcının kimlik bilgilerini içeren kayıt'], 'Yarı yapılandırılmış görüşme formu bir rehberdir; ana sorular sabit olsa da sıralama ve ifade görüşmenin akışına göre uyarlanabilir.'),
  ('Yapılandırılmamış görüşmelerde görüşmeci becerisinin özellikle önemli olmasının nedeni nedir?', 'Görüşmenin yönü büyük ölçüde görüşmecinin anlık kararlarına bağlıdır', ['Görüşmeci her soruyu önceden yazılmış bir metinden aynen okumak zorundadır', 'Görüşmecinin katılımcıyla göz teması kurması kesinlikle yasaktır', 'Görüşmeler en fazla beş dakika ile sınırlı tutulmak zorundadır'], 'Hazır sorular olmadığı için görüşmeci neyin izleneceğine, ne zaman derinleşileceğine anında karar verir; bu da deneyim ve beceri gerektirir.'),
  ('Aşağıdaki konulardan hangisi odak grup görüşmesi için en az uygundur?', 'Katılımcıların kişisel borç ve aile içi sorunları', ['Yeni bir okul logosu taslağına ilişkin ilk izlenimler ve beğeniler', 'Mahalle parkının yenilenmesine yönelik öneriler', 'Bir ders kitabının dili hakkındaki görüşler'], 'Çok kişisel ve hassas konular grup önünde rahatça konuşulamaz; bu tür konular bireysel ve gizli görüşmelerle daha iyi incelenir.'),
  ('Odak grup görüşmelerinde katılımcıların, gruptaki çoğunluk görüşüne uyarak kendi gerçek düşüncelerini dile getirmemesine ne ad verilir?', 'Grup düşüncesi', ['Hawthorne (izlenme) etkisi', 'Kartopu etkisi', 'Yenilik etkisi'], 'Grup baskısı, katılımcıların farklı görüşlerini saklayıp çoğunluğa uymasına yol açabilir; bu, odak grupların bilinen bir sınırlılığıdır.'),
  ('Bir şirket yeni bir ürünün ambalajı hakkında hızlıca fikir almak için 8 tüketiciyi bir araya getirip 90 dakikalık bir tartışma düzenliyor. Bu bulgular en doğru biçimde nasıl kullanılmalıdır?', 'Fikir üretmek ve sonraki geniş ölçekli araştırmayı yönlendirmek için', ['Tüm tüketicilerin yüzde kaçının ambalajı beğendiğini hesaplamak için', 'Ürünün satışlarının kesin olarak artacağını ve kâr getireceğini kanıtlamak için', 'Ülkedeki tüketici evreninin tamamını temsil eden oranlar elde etmek için'], 'Küçük ve seçilmiş bir grup istatistiksel genellemeye uygun değildir; odak grup bulguları keşif ve fikir üretimi için değerlidir.'),
  ('Görüşmede katılımcı yanıtını bitirdikten sonra görüşmecinin birkaç saniye sessiz kalıp beklemesi hangi amaca hizmet eder?', 'Katılımcıyı düşüncesini sürdürmeye ve ayrıntı eklemeye teşvik etmek', ['Görüşmenin artık sona erdiğini katılımcıya açıkça ve kesin olarak bildirmek', 'Katılımcının yanıtını onaylamadığını ve yanlış bulduğunu göstermek', 'Ses kayıt cihazının pilini değiştirmek için zaman kazanmak'], 'Sessiz sondaj, katılımcıya düşünmesi için alan tanır ve çoğu zaman ek ayrıntıların anlatılmasını sağlar.'),
  ('Aşağıdakilerden hangisi tarafsız bir sondaj sorusudur?', 'Bunu biraz daha açabilir misiniz?', ['Bu sizi çok üzmüş olmalı, değil mi?', 'Yani okul yönetimi haksızlık yaptı diyorsunuz?', 'Herkes gibi siz de buna öfkelenmişsinizdir?'], 'Tarafsız sondaj, katılımcıya bir yorum ya da duygu önermez; diğer seçenekler yanıtı belirli bir yöne çeker.'),
  ('Bir görüşmeci katılımcının her yanıtından sonra \'Harika, çok doğru!\' gibi onaylayıcı yorumlar yapıyor. Bu davranışın veriye olası etkisi nedir?', 'Katılımcı görüşmecinin beğendiği türden yanıtlar vermeye yönelebilir', ['Katılımcının yanıtları tamamen ve kesin olarak nesnel hâle gelir', 'Görüşme yapılandırılmış görüşmeye dönüşür ve standartlaşır', 'Katılımcının yanıtları hiçbir koşulda değişmez'], 'Görüşmecinin seçici onayı bir ödül işlevi görür; katılımcı onay alan yanıtları daha çok vermeye başlayabilir.'),
  ('Kadınların iş yerinde yaşadığı ayrımcılık deneyimleri üzerine bir araştırmada görüşmelerin kadın görüşmecilerce yapılması hangi gerekçeyle savunulabilir?', 'Katılımcıların deneyimlerini daha rahat anlatabileceği gerekçesiyle', ['Kadın görüşmecilerin daha az ücret istediği ve maliyeti azalttığı gerekçesiyle', 'Erkek görüşmecilerin yasal olarak görüşme yapamayacağı gerekçesiyle', 'Görüşmenin yapılandırılmış hâle gelip standartlaşacağı gerekçesiyle'], 'Hassas konularda görüşmecinin katılımcıyla bazı özellikleri paylaşması güveni artırabilir ve görüşmeci etkisini azaltabilir.'),
  ('Bir öğrencinin okul müdürü tarafından, müdürün odasında, okul disiplini hakkında görüşmeye alınması veri kalitesi açısından neden sorunludur?', 'Güç ilişkisi öğrencinin açık konuşmasını engelleyebilir', ['Müdürün odası ses kaydı yapmak için yeterince ve gerektiği kadar büyük değildir', 'Öğrencilerin hiçbir koşulda görüşmeye katılması mümkün değildir', 'Görüşme doğal olarak açık uçlu sorular içeremez'], 'Görüşmeci ile katılımcı arasındaki güç farkı ve ortam, katılımcının kendini sansürlemesine yol açabilir.'),
  ('Sözlü tarih görüşmelerinden elde edilen bilgilerin değerlendirilmesinde araştırmacının özellikle dikkat etmesi gereken nokta hangisidir?', 'Anıların zamanla değişip yeniden yorumlanmış olabileceği', ['Anlatıların her zaman yazılı belgelerden daha kesin ve güvenilir olduğu', 'Tanıkların tümünün aynı olayları birbirinin aynısı biçimde hatırladığı', 'Görüşmelerin yalnızca sayısal veriler ve istatistikler ürettiği'], 'Bellek seçicidir ve sonradan öğrenilenlerle yeniden biçimlenebilir; bu nedenle sözlü anlatılar başka kaynaklarla karşılaştırılarak değerlendirilir.'),
  ('Bir konuda uzmanlardan oluşan bir panelin, birbirini görmeden ve adları gizli tutularak birkaç tur boyunca anket yanıtlaması ve her turda önceki turun özetini görerek görüşünü yeniden değerlendirmesine dayanan teknik hangisidir?', 'Delphi tekniği', ['Odak grup görüşmesi', 'Kartopu örneklemesi', 'Panel anketi'], 'Delphi tekniği, uzmanlar arasında adsız ve yinelemeli geri bildirimle görüş birliği arar.'),
  ('Delphi tekniğinde uzmanların kimliklerinin birbirinden gizli tutulmasının temel amacı nedir?', 'Statüsü yüksek kişilerin diğerlerini etkilemesini önlemek', ['Uzmanlara ödenecek ücreti azaltmak ve bütçeyi küçültmek', 'Uzmanların birbirleriyle her turda doğrudan tartışmasını sağlamak', 'Turların sayısını tek bir tura indirmek'], 'Adsızlık, ünlü ya da baskın bir uzmanın görüşlerinin diğerlerini yönlendirmesini engeller; bu da odak gruplardaki uyma baskısından kaçınmayı sağlar.'),
  ('Bir okulun 30 öğretmeninin hizmet içi eğitim ihtiyacı belirlenecektir. Bu durumda örneklem seçmek yerine tüm öğretmenlere ulaşmak neden daha uygundur?', 'Evren küçük ve tamamına ulaşılabilir olduğu için', ['Örneklem seçmek yasal düzenlemelerle her durumda açıkça yasaklandığı için', 'Öğretmenlerin çoğunluğu ankete yanıt vermeyeceği ve veri toplanamayacağı için', 'Sayım her zaman örneklemden daha ucuz ve daha hızlı olduğu için'], 'Evren küçük ve erişilebilir olduğunda tamamını incelemek örnekleme hatasını ortadan kaldırır ve maliyeti kabul edilebilir düzeyde tutar.'),
  ('Bir meyve suyu fabrikasında kalite kontrol için her şişenin açılıp tadılmaması, örneklem kullanılmasını hangi gerekçeyle zorunlu kılar?', 'İnceleme işlemi birimleri tükettiği için', ['Fabrikadaki şişelerin her birinin diğerlerinden tamamen farklı olduğu için', 'Şişe sayısının herhangi bir yöntemle bilinmesinin imkânsız olduğu için', 'Kalite kontrolün yasal olarak yalnızca örneklemle yapılması gerektiği için'], 'Yıkıcı testlerde (şişeyi açmak, ampulü ömrü bitene kadar yakmak gibi) tam sayım bütün ürünü yok eder; bu yüzden örneklem şarttır.'),
  ('Örneklem çerçevesinde aynı kişinin iki kez yer alması ne gibi bir sonuç doğurur?', 'O kişinin seçilme olasılığı diğerlerinden yüksek olur', ['O kişi örnekleme hiçbir koşulda ve hiçbir aşamada seçilemez', 'Örneklem büyüklüğü kendiliğinden yarıya iner', 'Çerçevedeki diğer kişilerin seçilme olasılığı artar'], 'Mükerrer kayıtlar, ilgili birimlerin seçilme olasılığını artırarak eşit olasılık varsayımını bozar.'),
  ('Bir üniversitenin öğrencileri üzerine yapılacak bir araştırmada üç yıl önceki kayıt listesi örneklem çerçevesi olarak kullanılıyor. Bu çerçevenin temel sorunu nedir?', 'Yeni kayıt olanları içermemesi ve mezun olanları içermesi', ['Listedeki tüm öğrencilerin aynı bölümde okuyor ve aynı yaşta olması', 'Listenin alfabetik sırada olup başka türlü sıralanamaması', 'Listede öğrencilerin yalnızca adlarının ve numaralarının yer alması'], 'Güncel olmayan çerçeve, evrene artık ait olmayan birimleri içerir ve yeni birimleri dışarıda bırakır; bu kapsam sorunlarına yol açar.'),
  ('200 kişilik bir evrenden basit rastgele örneklemeyle 50 kişi seçilecektir. Belirli bir kişinin örnekleme girme olasılığı nedir?', '1/4', ['1/50', '1/200', '1/2'], 'Her birimin seçilme olasılığı n/N = 50/200 = 1/4\'tür.'),
  ('Ülke çapında dağılmış bir evrende basit rastgele örneklemenin pratik bir sakıncası nedir?', 'Seçilen kişiler çok dağınık olacağından ulaşım maliyeti yüksektir', ['Her bireyin seçilme olasılığı birbirinden farklı ve eşitsiz olur', 'Seçim işlemi araştırmacının kişisel tercihine ve yargısına bağlıdır', 'Örneklem büyüklüğü hiçbir zaman önceden belirlenemez'], 'Rastgele seçilen kişiler ülkenin her yerine dağılabilir; yüz yüze görüşmede bu durum yol ve zaman maliyetini artırır. Bu yüzden küme örneklemesi tercih edilebilir.'),
  ('800 öğrencilik listeden 40 öğrenci sistematik örneklemeyle seçilecek ve 1 ile 20 arasından rastgele seçilen başlangıç sayısı 7 çıkmıştır. Örnekleme giren beşinci öğrencinin listedeki sıra numarası kaçtır?', '87', ['107', '67', '27'], 'k = 800/40 = 20. Seçilenler 7, 27, 47, 67, 87, … olur; beşinci öğrenci 7 + 4×20 = 87. sıradadır.'),
  ('Bir okulda 600 dokuzuncu, 300 onuncu ve 100 on birinci sınıf öğrencisi vardır. Orantılı tabakalı örneklemeyle toplam 200 öğrenci seçilecekse onuncu sınıflardan kaç öğrenci alınmalıdır?', '60', ['67', '100', '20'], 'Onuncu sınıfların evrendeki payı 300/1.000 = %30\'dur. 200 × 0,30 = 60 öğrenci seçilir.'),
  ('Tabakalama değişkeni seçilirken hangi ölçüt gözetilmelidir?', 'Araştırılan konuyla ilişkili olduğu düşünülen bir özellik olması', ['Katılımcıların en kolay ulaşılabilecek kişiler olması', 'Tabaka sayısının mümkün olduğunca fazla tutulması', 'Tabakaların birbirine olabildiğince benzer olması'], 'Tabakalama, ilgilenilen değişkenle ilişkili özelliklere göre yapıldığında kesinliği artırır; tabakalar kendi içinde benzer, birbirinden farklı olmalıdır.'),
  ('Tabakalı örnekleme ile küme örneklemesi arasındaki temel fark aşağıdakilerden hangisidir?', 'Tabakalıda her alt gruptan seçim yapılır; kümede ise yalnızca bazı gruplar seçilir', ['Tabakalıda yalnızca gönüllüler alınır; kümede ise kura çekilir', 'Tabakalı yöntem nitel, küme yöntemi ise yalnızca nicel araştırmada kullanılır', 'Tabakalıda evren listesi gerekmez; kümede ise evrendeki her bireyin listesi gerekir'], 'Tabakalı örneklemede tüm tabakalar temsil edilir; küme örneklemesinde ise kümelerin yalnızca rastgele seçilen bir kısmı örnekleme girer.'),
  ('Küme örneklemesinin başlıca avantajı aşağıdakilerden hangisidir?', 'Evrendeki bireylerin tam listesi olmadan da uygulanabilmesi ve maliyetinin düşük olması', ['Aynı örneklem büyüklüğünde basit rastgele örneklemden daha kesin sonuç vermesi', 'Kümeler birbirine hiç benzemese bile örnekleme hatasının tamamen sıfıra inmesi', 'Araştırmacının katılımcıları kişisel yargısıyla belirleyebilmesi'], 'Yalnızca kümelerin listesi yeterlidir ve veri toplama birkaç bölgede yoğunlaştığı için ulaşım maliyeti azalır; ancak kesinlik genellikle daha düşüktür.'),
  ('Ulusal hane araştırmalarında çok aşamalı örneklemenin sık kullanılmasının başlıca nedeni nedir?', 'Ülkedeki tüm bireylerin tek bir güncel listesi olmadan uygulanabilmesi', ['Her bireyin seçilme olasılığının kesin olarak sıfır olması', 'Araştırmacının bölgeleri ve haneleri kişisel tercihine göre seçmesine izin vermesi', 'Görüşmecilerin tüm ülkeyi dolaşmasını zorunlu kılması'], 'Çok aşamalı tasarımda her aşamada yalnızca o düzeyin listesi gerekir; ayrıca görüşmeler seçilen bölgelerde toplandığı için maliyet düşer.'),
  ('Bir araştırmacı önce bir ildeki 50 liseden 8\'ini rastgele seçiyor, sonra her okulun öğrenci listesinden rastgele 40\'ar öğrenci seçiyor. Örneklemde toplam kaç öğrenci vardır ve yöntem nedir?', '320 öğrenci; iki aşamalı örnekleme', ['400 öğrenci; tabakalı örnekleme', '2.000 öğrenci; küme örneklemesi', '320 öğrenci; kota örneklemesi'], 'Önce okullar, sonra okullardan öğrenciler rastgele seçildiği için yöntem iki aşamalı örneklemedir; 8 × 40 = 320 öğrenci.'),
  ('Kolay ulaşılabilir örneklemenin hangi araştırma durumunda kullanılması en savunulabilirdir?', 'Bir anketin anlaşılırlığını sınayan ön çalışmada', ['Bir ülkedeki seçim sonucunu tahmin eden araştırmada', 'Nüfusun yüzde kaçının bir hastalığa sahip olduğunu kestirmede', 'Ulusal işsizlik oranının resmî olarak hesaplanmasında'], 'Pilot ya da keşif çalışmalarında amaç genelleme değil fikir ve sorun saptamadır; bu durumda kolay ulaşılabilir örneklem pratik ve kabul edilebilirdir.'),
  ('Kolay ulaşılabilir örneklemeye örnek olarak verilen \'üniversite öğrencilerinin sık kullanılması\' durumu, insan davranışı araştırmalarında hangi kaygıyı doğurur?', 'Bulguların genç ve eğitimli bir kesime özgü olabileceği', ['Öğrencilerin ankete yanıt vermesinin yasal olarak yasak olması', 'Öğrencilerin her zaman yanlış yanıt verdiğinin kanıtlanmış olması', 'Öğrencilerden veri toplamanın çok pahalı ve zaman alıcı olması'], 'Kolay ulaşıldığı için öğrencilerle yapılan çalışmalar yaygındır; ancak bu grup yaş, eğitim ve yaşam koşulları bakımından genel nüfustan farklıdır.'),
  ('Bir araştırmacı nadir bir hastalığa sahip kişilerle görüşmek istiyor; bu kişilerin resmî bir listesi yok. İlk görüştüğü iki hastadan tanıdıkları başka hastaları önermelerini istiyor. Bu yöntemin temel sınırlılığı nedir?', 'Örneklemin aynı sosyal çevredeki kişilerden oluşması', ['Her bireyin seçilme olasılığının eşit ve önceden hesaplanabilir olması', 'Hiçbir yeni katılımcıya ve yeni bilgiye ulaşılamaması', 'Çok kısa sürede yüz binlerce katılımcıya ulaşılması'], 'Önerilen kişiler öneren kişinin çevresinden geldiği için örneklem birbirine bağlı ve benzer kişilerden oluşabilir; yalnız ya da çevresi olmayan hastalar dışarıda kalır.'),
  ('Kartopu örneklemesinin olasılıksız bir örnekleme yöntemi sayılmasının nedeni nedir?', 'Bireylerin seçilme olasılıkları bilinmediği ve eşit olmadığı için', ['Her zaman çok küçük örneklemlerle uygulandığı için', 'Yalnızca nitel araştırmalarda kullanıldığı için', 'Katılımcılardan bilgilendirilmiş onam alınmadan ve gizlice yapıldığı için'], 'Kimin örnekleme gireceği önerme zincirine bağlıdır; evrendeki her bireyin seçilme olasılığı hesaplanamaz.'),
  ('Bir araştırmacı köy okullarındaki birleştirilmiş sınıf uygulamalarını incelerken farklı bölgelerden, farklı büyüklükteki ve farklı deneyimdeki öğretmenlerin bulunduğu okulları bilerek seçiyor. Bu hangi amaçlı örnekleme türüdür?', 'Maksimum çeşitlilik örneklemesi', ['Homojen örnekleme', 'Aşırı durum örneklemesi', 'Kolay ulaşılabilir (uygun) örneklemesi'], 'Maksimum çeşitlilik örneklemesinde birbirinden olabildiğince farklı durumlar seçilir; böylece bu farklılıklara rağmen ortak örüntüler aranır.'),
  ('Bir araştırmacı yalnızca ilk yılını dolduran ve aynı branşta çalışan genç öğretmenlerle odak grup yapıyor. Bu hangi amaçlı örnekleme türüdür?', 'Homojen örnekleme', ['Maksimum çeşitlilik örneklemesi', 'Aşırı durum örneklemesi', 'Sistematik örnekleme'], 'Homojen örneklemede belirli bir özelliği paylaşan kişiler seçilir; bu, o alt grubun deneyimini derinlemesine incelemeyi sağlar.'),
  ('Bir araştırmacı \'en az beş yıl deneyimi olan ve özel gereksinimli öğrencilerle çalışmış sınıf öğretmenleri\' koşulunu sağlayan kişileri örnekleme alıyor. Bu yaklaşıma ne ad verilir?', 'Ölçüt örneklemesi', ['Kartopu örneklemesi', 'Basit rastgele örnekleme', 'Gönüllü yanıt örneklemesi'], 'Ölçüt örneklemesinde önceden belirlenmiş koşulları karşılayan tüm ya da bazı durumlar seçilir.'),
  ('Amaçlı örneklemenin olasılıklı örneklemeye göre daha uygun olduğu durum hangisidir?', 'Az sayıda bilgi zengini durumu derinlemesine incelemek gerektiğinde', ['Bir özelliğin evrendeki oranını belirli bir hata payıyla kestirmek gerektiğinde', 'Ulusal seçim sonucunu tahmin etmek gerektiğinde', 'Bir ürünün bütün tüketicilerdeki memnuniyet oranını bulmak gerektiğinde'], 'Amaçlı örnekleme genelleme değil derinlemesine anlama hedefleyen nitel araştırmalara uygundur; oran tahmini için olasılıklı örnekleme gerekir.'),
  ('Kota örneklemesini tabakalı örneklemeden ayıran temel özellik nedir?', 'Alt gruplar içindeki seçimin rastgele yapılmaması', ['Evrenin alt gruplara hiç ayrılmaması', 'Alt grup oranlarının hiçbir aşamada dikkate alınmaması', 'Yalnızca kümelerin bütün olarak seçilmesi'], 'İki yöntemde de evren alt gruplara ayrılır; ancak tabakalıda her tabakadan rastgele seçim yapılırken kotada kişiler görüşmecinin tercihine ya da rastlantıya bırakılır.'),
  ('Olasılıklı örnekleme yöntemlerini olasılıksız yöntemlerden ayıran temel özellik nedir?', 'Evrendeki her birimin seçilme olasılığının bilinmesi ve sıfırdan büyük olması', ['Örneklemin her zaman en az 1.000 kişiden oluşması', 'Araştırmacının katılımcıları kendi kişisel yargısına ve deneyimine göre seçmesi', 'Katılımcıların ankete kendi istekleriyle katılması'], 'Olasılıklı örneklemede seçim şansa dayanır ve her birimin seçilme olasılığı hesaplanabilir; bu da örnekleme hatasının kestirilmesini sağlar.'),
  ('Bir araştırmacı ülke genelinde gençlerin internet kullanım süresini belirli bir hata payıyla tahmin etmek istiyor. Aşağıdaki yöntemlerden hangisini seçmesi en uygundur?', 'Tabakalı rastgele örnekleme', ['Kartopu örneklemesi', 'Gönüllü çevrimiçi anket', 'Kolay ulaşılabilir örnekleme'], 'Hata payıyla tahmin yapabilmek için olasılıklı bir yöntem gerekir; tabakalı rastgele örnekleme ayrıca bölge ve yaş gibi alt grupların temsilini güvenceye alır.'),
  ('Bir mahalle derneği yalnızca Facebook grubundaki üyelerine anket gönderip \'mahalle sakinlerinin görüşü\' olarak sonuç açıklıyor. Bu durumda örneklem çerçevesi ile evren arasındaki uyumsuzluk nedir?', 'Evren tüm mahalle sakinleri, çerçeve ise yalnızca grup üyeleridir', ['Evren yalnızca grup üyeleri, çerçeve ise tüm mahalle sakinleridir', 'Evren ve çerçeve tamamen aynı kişilerden oluşmaktadır', 'Çerçevede mahalle dışından hiçbir kişi bulunamaz'], 'Sosyal medya grubunda olmayan sakinler örnekleme giremez; sonuçlar yalnızca grup üyelerine genellenebilir.'),
  ('Aynı evrenden aynı yöntemle çekilen iki ayrı rastgele örneklemde ortalama boy 168,2 cm ve 167,6 cm bulunmuştur. Bu farkın en olası açıklaması nedir?', 'Örnekleme hatası', ['Evrenin iki ölçüm arasında tamamen değişmesi', 'Ölçümlerden birinin mutlaka hatalı yapılması', 'Örneklem çerçevesinin iki kez değiştirilmesi'], 'Rastgele örneklemler şansa bağlı olarak birbirinden biraz farklı sonuç verir; küçük farklar beklenen örnekleme değişkenliğidir.'),
  ('Bir kamuoyu araştırması \'%95 güven düzeyinde hata payı ±3 puan\' olarak açıklanmış ve bir görüşü destekleyenler %46 bulunmuştur. Bu bilgi en doğru biçimde nasıl yorumlanır?', 'Evrendeki gerçek oranın büyük olasılıkla %43 ile %49 arasında olduğu', ['Evrendeki gerçek oranın kesinlikle tam %46 olduğu', 'Katılımcıların %3\'ünün sorulara yanlış ya da eksik yanıt vermiş olduğu', 'Gerçek oranın %95 olasılıkla tam olarak %49 olduğu'], 'Hata payı, tahminin etrafında bir aralık tanımlar: %46 ± 3 = %43–%49. %95 güven, bu yöntemin uzun vadede gerçek değeri yakalama oranını anlatır.'),
  ('%95 güven düzeyinde bir oran için hata payı yaklaşık 1/√n kuralıyla kestirilebilir. 400 kişilik basit rastgele örneklemde en yüksek hata payı yaklaşık kaç puandır?', '±5 puan', ['±2 puan', '±4 puan', '±10 puan'], '1/√400 = 1/20 = 0,05, yani yaklaşık ±5 puan.'),
  ('Bir anket A adayına %48, B adayına %45 destek bulmuş ve hata payını ±3 puan olarak açıklamıştır. Bu sonuçla ilgili en doğru değerlendirme hangisidir?', 'Aradaki fark hata payı içinde kaldığından kesin bir önde olma sonucu çıkarılamaz', ['A adayının seçimi kesinlikle ve büyük bir farkla kazanacağı rahatlıkla söylenebilir', 'B adayının aslında önde olduğu kesin olarak bilinmektedir', 'Hata payı açıklandığı için iki adayın oyları eşit kabul edilmelidir'], 'A için aralık %45–%51, B için %42–%48\'dir; aralıklar örtüştüğü için hangi adayın gerçekten önde olduğu bu veriyle kesinleşmez.'),
  ('Görüşleri birbirine çok benzeyen bir evrene göre görüşleri çok farklılaşan bir evrende aynı kesinliği elde etmek için ne gerekir?', 'Daha büyük bir örneklem', ['Daha küçük bir örneklem', 'Aynı büyüklükte örneklem', 'Örnekleme gerek yoktur'], 'Evrendeki değişkenlik arttıkça rastgele örneklemler arasındaki dalgalanma da artar; aynı kesinlik için daha fazla birim gerekir.'),
  ('Nitel bir görüşme çalışmasında araştırmacının yeni görüşmelerden artık yeni tema çıkmadığını fark edip görüşmeleri sonlandırmasına ne ad verilir?', 'Veri doygunluğu', ['Örnekleme hatası', 'Kapsam hatası', 'Kota dolumu'], 'Doygunluk noktası, ek verinin artık yeni bilgi ya da kategori üretmediği aşamadır ve nitel çalışmalarda örneklem büyüklüğünün belirlenmesinde kullanılır.'),
  ('Bir belediye ulaşım anketini yalnızca hafta içi sabah saatlerinde metro istasyonlarında uyguluyor. Sonuçların hangi gruba genellenmesi en uygundur?', 'Hafta içi sabah metro kullananlara', ['Kentte yaşayan tüm yetişkinlere', 'Yalnızca otomobille işe gidenlere', 'Ülkedeki tüm toplu taşıma kullanıcılarına'], 'Örneklem yalnızca belirli saatte metroyu kullananlardan oluştuğu için sonuçlar en güvenli biçimde bu gruba genellenebilir.'),
  ('Bir hastanenin kalp hastalığı üzerine yaptığı araştırmada yalnızca hastaneye başvuran hastalar incelenmiştir. Bu örneklem hangi açıdan evreni (tüm kalp hastalarını) temsil etmeyebilir?', 'Hafif belirtili ve hastaneye başvurmayan hastalar dışarıda kalmıştır', ['Hastaneye başvuran hastaların sayısı her zaman çok azdır', 'Hastalardan alınan onam formları geçersiz sayılmaktadır', 'Hastane kayıtlarında hastaların yaş ve cinsiyet bilgileri yer almamaktadır'], 'Hastaneye başvuranlar genellikle daha ağır vakalardır; hafif vakalar ya da sağlık hizmetine erişemeyenler örneklemde yer almaz.'),
  ('Örnekleme yanlılığını en etkili biçimde azaltan yaklaşım hangisidir?', 'Uygun bir çerçeveden olasılıklı yöntemle seçim yapmak', ['Örneklemi yalnızca gönüllülerden oluşturup büyütmek', 'Görüşmecilerin katılımcıları kendi istekleriyle ve kolaylığa göre seçmesi', 'Anket sorularının sayısını artırmak'], 'Olasılıklı seçim, kimin örnekleme gireceğini araştırmacının ya da katılımcının tercihinden bağımsız kılar; iyi bir çerçeve de kapsam sorunlarını azaltır.'),
  ('Bir anket evden eve yürütülürken görüşmeci kapıyı açan ilk kişiyle görüşüyor. Bu uygulamanın olası sorunu nedir?', 'Evde daha çok bulunan ya da kapıyı açmaya daha yatkın kişilerin öne çıkması', ['Her hanede tam olarak iki kişinin ve aynı yaşta bireylerin görüşmeye katılması', 'Örneklemin her zaman yalnızca çocuklardan ve gençlerden oluşması', 'Hane listesinin örneklem çerçevesi olarak hiçbir şekilde kullanılamaması'], 'Hane içinden kişi seçimi de rastgele yapılmalıdır (ör. en son doğum günü olan yetişkin); aksi hâlde belirli hane üyeleri sistematik olarak öne çıkar.'),
  ('Bir araştırmacı rastgele örneklem seçtikten sonra cinsiyet dağılımının evrendekinden farklı çıktığını görüyor ve az temsil edilen gruba ait yanıtlara daha fazla ağırlık veriyor. Bu işleme ne ad verilir?', 'Ağırlıklandırma', ['Kartopu genişletme', 'Pilot uygulama', 'Kodlama'], 'Ağırlıklandırma, örneklemdeki grup oranlarını bilinen evren oranlarına uydurmak için yanıtlara farklı katsayılar verilmesidir.'),
  ('Yüz yüze derinlemesine görüşmelerde katılımcıya tam anonimlik değil gizlilik sözü verilebilmesinin nedeni nedir?', 'Görüşmeci katılımcıyı yüz yüze tanıdığı için', ['Görüşmelerde hiçbir kişisel bilgi konuşulmadığı ve kayıt tutulmadığı için', 'Görüşme dökümlerinin her zaman katılımcının adıyla yayımlanması zorunlu olduğu için', 'Görüşmelerde onam almak yasal olarak gerekmediği ve istenmediği için'], 'Görüşmeci kiminle konuştuğunu bildiği için kimlik tamamen gizli değildir; yapılabilecek olan, kimliği raporlarda ve veri dosyalarında korumaktır.'),
  ('Küçük bir köyde yapılan görüşmelerde katılımcının adı yazılmasa da \'köyün tek ebesi olan 60 yaşındaki kadın\' gibi bir betimleme kullanılmasının sorunu nedir?', 'Ayrıntılar kişinin kolayca tanınmasına yol açabilir', ['Betimleme katılımcının yaşını gereğinden fazla küçük ya da yanlış göstermektedir', 'Görüşme dökümünün tamamen geçersiz sayılmasına ve silinmesine neden olur', 'Ebelerin araştırmalara katılması yasal olarak yasaklanmıştır'], 'Küçük topluluklarda meslek, yaş gibi ayrıntılar bir araya geldiğinde kişiyi tanınır kılar; bu dolaylı kimlik açığa çıkmasıdır.'),
  ('Bir öğretmenin kendi öğrencilerinden not verdiği bir derste ankete katılmalarını istemesi hangi etik kaygıyı doğurur?', 'Öğrencilerin kendilerini katılmak zorunda hissedebilmesi', ['Öğrencilerin ankete katılmasının her durumda yasal olarak yasak olması', 'Anketin soru sayısının gereğinden fazla ve uzun olması', 'Öğrencilerin kimliklerinin her zaman kesin olarak anonim kalması'], 'Öğretmen ile öğrenci arasındaki güç ilişkisi, gönüllülüğü zayıflatabilir; öğrenciler katılmamanın notlarını etkileyeceğinden korkabilir.'),
  ('Bir araştırmacı sosyal medyadaki herkese açık bir forumda insanların yazışmalarını inceliyor. Etik açıdan en uygun yaklaşım hangisidir?', 'Kullanıcı adlarını ve tanınmayı sağlayacak alıntıları gizleyerek çalışmak', ['Kullanıcı adlarını ve tam alıntıları raporda olduğu gibi yayımlamak', 'İletiler herkese açık olduğu için hiçbir etik değerlendirme yapmadan çalışmak', 'Kullanıcılarla iletişime geçip onları tartışmaya kışkırtmak'], 'Herkese açık olması verinin her biçimde kullanılabileceği anlamına gelmez; tam alıntılar arama motorlarıyla kişiye ulaştırabilir, bu yüzden kimlik koruması gerekir.'),
  ('Bir araştırmacı öğrencilerin teneffüs davranışlarını gözlemledikten sonra aynı öğrencilerle görüşmeler yapıyor. Bu ikinci adım en çok hangi katkıyı sağlar?', 'Gözlenen davranışların öğrenciler için ne anlama geldiğini öğrenmeyi', ['Gözlemin hiç yapılmamış gibi kabul edilip gözlem verilerinin tümüyle silinmesini', 'Örneklemin otomatik olarak ve kendiliğinden genişlemesini', 'Gözlemci etkisinin geriye dönük olarak tamamen silinmesini'], 'Gözlem ne olduğunu, görüşme ise bunun nedenini ve anlamını ortaya koyar; iki yöntem birbirini tamamlar.'),
  ('Bir okul yönetimi ankette öğrencilerin %90\'ının kütüphaneyi \'sık kullandığını\' bulmuş; ancak kütüphane giriş kayıtları çok düşük kullanım göstermektedir. Bu çelişki en çok neyi düşündürür?', 'Anket yanıtlarının sosyal beğenirlikten etkilenmiş olabileceğini', ['Giriş kayıtlarının her zaman anketten daha az güvenilir bir kaynak olduğunu', 'Öğrencilerin kütüphaneye gizlice girdiğinin kanıtlandığını', 'Anketin tam sayım olduğu için kesinlikle doğru olduğunu'], 'Davranışa dayalı kayıtlar ile beyanlar çeliştiğinde, beyanlar sıklıkla toplumsal beklentiye göre şişirilmiştir. Bu, üçgenlemenin değerini gösterir; \'sık\' sözcüğünün belirsizliği de etkili olabilir.'),
  ('Bir araştırmacı lise öğrencilerinin sınav dönemlerinde ne kadar uyuduklarını öğrenmek istiyor. Hangi yöntem bilgiyi en az bellek hatasıyla toplar?', 'Öğrencilerin her sabah doldurduğu uyku günlüğü', ['Dönem sonunda tüm öğrencilere yapılan tek seferlik anket', 'Öğretmenlerle yapılan görüşmeler', 'Bir yıl sonra yapılan odak grup'], 'Günlük tutma yöntemi, davranış gerçekleştikten kısa süre sonra kayıt yapıldığı için uzun süreli hatırlamaya dayanan yöntemlerden daha doğrudur.'),
  ('Aşağıdaki araştırma amaçlarından hangisi için odak grup görüşmesi en uygun yöntemdir?', 'Yeni bir gençlik merkezi için gençlerin önerilerini tartışarak geliştirmek', ['Ülkedeki gençlerin yüzde kaçının düzenli olarak spor yaptığını kesin olarak belirlemek', 'Bir sınıftaki öğrencilerin teneffüs davranışlarını saymak', 'Bir hastanın ilaç kullanım öyküsünü gizli biçimde öğrenmek'], 'Odak gruplar fikirlerin etkileşimle geliştiği durumlarda güçlüdür; oran tahmini, davranış sayımı ve çok kişisel konular için uygun değildir.'),
  ('Bir araştırmacı bir fabrikadaki işçilerin iş güvenliği kurallarına ne ölçüde uyduğunu öğrenmek istiyor. Yalnızca işçilere anket uygulamanın zayıflığı nedir?', 'İşçiler kurallara uyduklarını olduğundan fazla bildirebilir', ['İşçilerin önemli bir bölümünün okuma yazma bilmediğinin kesin olması', 'Anket fabrikada hiçbir koşulda uygulanamaz', 'Anket sonuçları her zaman gözlemden daha kesin sonuç verir'], 'Kurala uyum toplumca beklenen bir davranıştır; beyanlar gerçek uyumu abartabilir. Bu nedenle gözlem ya da kayıtlarla desteklenmelidir.'),
  ('Bir hastanenin bekleme süreleri hakkında hem hasta kayıt sisteminden alınan zaman damgaları hem de hasta memnuniyet anketi kullanılıyor. Bu iki veri kaynağı arasındaki temel fark nedir?', 'Kayıtlar gerçekleşen süreyi, anket ise algılanan deneyimi yansıtır', ['Kayıtlar algılanan deneyimi, anket ise gerçekleşen süreyi yansıtır', 'Kayıtlar ve anket, hastaların yalnızca duygularını ve beklentilerini ölçer', 'Her iki kaynak da tamamen aynı bilgiyi verir'], 'Kurum kayıtları nesnel süreyi verir; anket ise hastaların bu süreyi nasıl algıladığını gösterir. İkisi birlikte daha bütünlüklü bir tablo sunar.'),
  ('İkincil veri kullanmanın birincil veri toplamaya göre temel sınırlılığı aşağıdakilerden hangisidir?', 'Verinin araştırmacının sorusuna tam uymayabilmesi', ['Verinin toplanmasının her zaman çok daha pahalı olması', 'Verilere hiçbir koşulda erişilememesi ve yasak olması', 'Verinin araştırmacının kendisi tarafından toplanmış olması'], 'İkincil veri başka bir amaçla toplandığı için değişkenler, tanımlar ya da kapsam araştırmacının sorusuyla tam örtüşmeyebilir.'),
  ('Bir öğrenci yerel tarih ödevi için mahallesindeki yaşlılarla görüşüyor, ayrıca belediye arşivindeki eski haritaları inceliyor. Bu iki kaynağı birlikte kullanmasının yararı nedir?', 'Bir kaynağın eksiklerini diğeriyle kontrol edebilmek', ['Görüşmeleri gereksiz kılıp arşiv bilgisini tek kaynak yapmak', 'Haritaların tarihlerini görüşmelerle tamamen değiştirmek', 'Ödevin süresini ve emeğini mümkün olduğunca uzatmak'], 'Anılar ve belgeler farklı türden hatalara açıktır; birlikte kullanıldıklarında birbirini doğrulayabilir ya da tamamlayabilir.'),
  ('Kurum kayıtlarını araştırmada kullanan bir araştırmacının dikkat etmesi gereken bir nokta hangisidir?', 'Kayıtların tutulma biçimi ve tanımlarının zaman içinde değişmiş olabileceği', ['Kurum kayıtlarının her zaman en doğru veri kaynağı olduğu kabul edilmelidir', 'Kayıtlarda geçen tüm kişilerin araştırmaya kendi istekleriyle ve onam vererek katıldığı', 'Kayıtların yalnızca nitel betimlemelerden oluştuğu ve sayılamayacağı'], 'Örneğin bir suç türünün tanımı ya da kayıt sistemi değiştiğinde yıllar arası artış gerçek bir değişimi değil kayıt değişikliğini yansıtabilir.'),
  ('Bir araştırmacı bir kafenin müşterilerinin masada ne kadar süre telefonla ilgilendiğini ölçmek istiyor. Gözlem formuna aşağıdaki kategorilerden hangisini koyması en uygundur?', 'Telefon ekranına bakılan süre', ['Müşterinin telefon bağımlısı olup olmadığı', 'Müşterinin sıkılıp sıkılmadığı', 'Müşterinin yalnızlık hissedip hissetmediği'], 'Gözlem kategorileri doğrudan görülebilen ve ölçülebilen davranışlara dayanmalıdır; bağımlılık, sıkılma ve yalnızlık gözlemcinin çıkarımını gerektirir.'),
  ('Bir öğretmen adayı staj okulunda bir öğretmenin derslerini izlerken \'öğretmen öğrencilere ne kadar süre bekleme süresi tanıyor\' sorusuna odaklanıyor. Bu durumda en uygun kayıt aracı hangisidir?', 'Soru sonrası bekleme süresinin saniye olarak kaydedildiği form', ['Öğretmenin kişiliği ve ders anlatım tarzı hakkında serbest izlenim notları', 'Öğrencilere dağıtılan Likert tipi memnuniyet anketi', 'Okul müdürüyle yapılan derinlemesine görüşme'], 'Araştırma sorusu ölçülebilir bir davranışla ilgilidir; doğrudan süre kaydı soruya en doğrudan yanıtı verir.'),
  ('Bir gözlemci iki ayrı sınıfta aynı formu kullanıyor; birinci sınıfta \'gürültü\' kategorisine 40, ikincide 12 işaret koyuyor. Ancak birinci sınıfı 80, ikinciyi 20 dakika gözlemlemiştir. Hangi sonuç doğrudur?', 'Dakika başına bakıldığında ikinci sınıfta gürültü daha sıktır', ['Birinci sınıf her durumda daha gürültülüdür', 'İki sınıfın gürültü düzeyi tam olarak aynıdır', 'Gözlem sürelerinin farklı olması karşılaştırmanın sonucunu hiç etkilemez'], 'Dakika başına oran birinci sınıfta 40/80 = 0,5, ikincide 12/20 = 0,6\'dır. Farklı gözlem sürelerinde ham sayılar değil oranlar karşılaştırılmalıdır.'),
  ('Bir hayvan davranışı araştırmacısı, kuşların sabahları daha çok öttüğünü ileri sürmek için yalnızca sabahları gözlem yapıyor. Bu çalışmanın tasarımındaki temel eksiklik nedir?', 'Karşılaştırma için diğer saatlerde gözlem yapılmamıştır', ['Gözlem kuşların doğal ortamında ve onları rahatsız etmeden yapılmıştır', 'Gözlem katılımsız olarak yürütülmüştür', 'Gözlemci kayıtlarını hemen yazıya geçirmiştir'], '\'Sabahları daha çok\' bir karşılaştırma iddiasıdır; bunu desteklemek için diğer zaman dilimlerinde de aynı yöntemle gözlem yapılmalıdır.'),
  ('Bir gözlemcinin yalnızca kendi beklentisini doğrulayan davranışları fark edip kaydetmesine ne ad verilir?', 'Gözlemci beklenti yanlılığı', ['Hawthorne (izlenme) etkisi', 'Kapsam hatası', 'Kartopu örneklemesi'], 'Gözlemci, beklediği şeyleri görme eğiliminde olabilir; bu nedenle kör gözlemciler ve açık tanımlı kategoriler kullanılır.'),
  ('Bir araştırmacı yeni bir okuma programının etkisini gözlemlemek için gözlemcilere hangi sınıfların programı uyguladığını söylemiyor. Bu önlemin amacı nedir?', 'Gözlemcilerin beklentilerinin kayıtları etkilemesini önlemek', ['Gözlemcilerin işini kolaylaştırıp gözlem süresini kısaltmak', 'Öğretmenlerin gözlemden haberdar olmasını tamamen engellemek', 'Örneklemi büyüterek örnekleme hatasını tamamen ve kesin olarak sıfıra indirmek'], 'Kör gözlem, gözlemcinin hangi grubun hangi koşulda olduğunu bilmemesidir ve beklenti yanlılığını azaltır.'),
  ('Bir okulda zorbalık davranışlarını incelemek isteyen bir araştırmacı için katılımsız gözlemin bir sınırlılığı aşağıdakilerden hangisidir?', 'Zorbalığın çoğu zaman yetişkinlerin göremeyeceği yerlerde yaşanması', ['Zorbalığın her zaman ve yalnızca sınıf içinde öğretmenin gözü önünde yaşanması', 'Gözlemcinin öğrencilerle aynı yaşta olmak zorunda olması', 'Gözlemin hiçbir zaman okul bahçesinde yapılamaması'], 'Gizlenen davranışlar gözlemcinin varlığında ortaya çıkmayabilir; bu tür konularda gözlem, adsız anket ya da görüşmeyle desteklenir.'),
  ('Bir gözlemci aynı gün içinde altı saat boyunca kesintisiz kodlama yapıyor ve son saatlerde daha az davranış kaydettiği görülüyor. Bu düşüşün yöntemsel açıklaması ne olabilir?', 'Gözlemci yorgunluğu nedeniyle dikkatin azalması', ['Sınıfın her zaman öğleden sonra tamamen sessizleşmesi', 'Gözlem formunun kendiliğinden ve fark edilmeden değişmesi', 'Hawthorne etkisinin gözlemciye geçmesi'], 'Uzun ve kesintisiz kodlama dikkat kaybına yol açar; molalar, daha kısa oturumlar ya da ikinci bir gözlemci bu sorunu azaltır. Davranış gerçekten de azalmış olabilir, bu yüzden kontrol gerekir.'),
  ('Bir araştırmacı süpermarkette müşterilerin hangi rafların önünde ne kadar durduğunu izlemek için güvenlik kameralarının kayıtlarını, mağaza izniyle ama müşterilere bilgi vermeden kullanmak istiyor. Bu tasarımda en çok hangi konu tartışılmalıdır?', 'Müşterilerin mahremiyeti ve verilerin kimliksizleştirilmesi', ['Örneklem büyüklüğünün yetersizliği', 'Anket sorularının yönlendirici ve yüklü biçimde yazılmış olması', 'Görüşmeci etkisinin büyüklüğü'], 'Kayıtlar kişileri tanınabilir biçimde içerir; yüzlerin bulanıklaştırılması, kimlik bilgisinin tutulmaması ve kamusal alan beklentisi gibi konular etik değerlendirme gerektirir.'),
  ('Gözlem verisi toplarken \'tam kayıt\' (olan her şeyi yazma) yerine \'odaklı gözlem\' yapmanın gerekçesi nedir?', 'Dikkatin sınırlı olması ve araştırma sorusuna odaklanmanın gerekmesi', ['Odaklı gözlemin hiçbir hazırlık ya da araştırma sorusu gerektirmemesi', 'Tam kaydın katılımcıların davranışlarını her zaman ve kesin olarak değiştirmesi', 'Odaklı gözlemin her durumda daha fazla sayıda gözlemci gerektirmesi'], 'İnsan dikkati sınırlıdır; araştırma sorusuyla ilgili davranışlara odaklanmak hem verinin kalitesini artırır hem de çözümlemeyi kolaylaştırır.'),
  ('\'Geçen yıl kaç kez sinemaya gittiniz?\' sorusu, \'Hayatınız boyunca yılda ortalama kaç kez sinemaya gittiniz?\' sorusuna göre neden daha iyi bir anket sorusudur?', 'Hatırlanması daha kolay, belirli bir zaman dilimini sorar', ['Daha uzun ve ayrıntılı olduğu için daha bilimsel görünür', 'Katılımcıyı sinemaya gitmeye teşvik eder ve yönlendirir', 'Yanıtların doğrudan Likert ölçeğine dönüştürülmesini sağlar'], 'Kısa ve belirli bir hatırlama dönemi bellek hatasını azaltır; ömür boyu ortalama gibi belirsiz ve uzun dönemler doğru yanıt vermeyi zorlaştırır.'),
  ('Bir anket formunda gelir sorusu \'Aylık geliriniz ne kadar?\' biçiminde açık uçlu olarak bırakılmıştır. Bu soruyu gelir aralıklarını içeren seçeneklere dönüştürmenin olası avantajı nedir?', 'Katılımcıların hassas bir soruyu yanıtlama isteğinin artması', ['Gelirin kuruşu kuruşuna ve tam olarak öğrenilmesi', 'Sorunun hiçbir katılımcı tarafından atlanmaması ve zorunlu olması', 'Yanıtların çözümlenmesinin tamamen gereksiz hâle gelmesi'], 'Kesin tutar vermek pek çok kişiye rahatsız edici gelir; geniş aralıklar daha az ifşa edici olduğu için yanıtlanma oranını artırabilir, ama ayrıntı kaybı yaratır.'),
  ('Bir anketteki \'Ailenizle iyi geçiniyor musunuz? (Evet / Hayır)\' sorusunun yanıt biçimindeki temel sorun nedir?', 'İki seçenek, ilişkinin derecesindeki farklılıkları yakalayamaz', ['Seçenekler birbiriyle çakışmakta ve aynı anlama gelmektedir', 'Soru açık uçlu olduğu için verilen yanıtlar hiçbir biçimde kodlanamaz', 'Seçenekler alfabetik sıraya göre dizilmediği için karışıktır'], 'Aile ilişkisi gibi derecelenebilen bir konuda yalnızca evet/hayır seçeneği yanıtları kabalaştırır; derecelendirme ölçeği daha uygun olur.'),
  ('Bir anketin uzunluğu 120 soruya çıkarıldığında anketin sonundaki soruların sıklıkla aynı seçenekle işaretlendiği görülüyor. Bu durum neyi gösterir?', 'Katılımcı yorgunluğunun yanıt kalitesini düşürdüğünü', ['Anketin sonundaki soruların en anlaşılır sorular olduğunu', 'Katılımcıların görüşlerinin anket boyunca hiç değişmediğini', 'Örneklemin evreni kusursuz biçimde temsil ettiğini'], 'Uzun anketlerde katılımcılar yorulur ve soruları okumadan işaretlemeye başlar; anket uzunluğu amaca göre sınırlı tutulmalıdır.'),
  ('Aşağıdaki anket sorularından hangisi en iyi yazılmıştır?', 'Geçen hafta kaç gün kahvaltı yaptınız?', ['Kahvaltı yapmanın önemini bilen biri olarak sağlıklı besleniyor musunuz?', 'Kahvaltı ve öğle yemeğini düzenli olarak yapar mısınız?', 'Sağlıklı bir kahvaltı yapmamanın zararlarını bilmiyor musunuz?'], 'İlk soru tek konulu, belirli bir zaman dilimine bağlı ve tarafsızdır. Diğerleri sırasıyla yönlendirici, çift namlulu ve çifte olumsuzluklu/yüklüdür.'),
  ('Bir öğrenci kulübü anketinde \'Kulübün etkinliklerinden memnun musunuz?\' sorusuna \'Memnunum\' diyenlerin oranı %92 bulunmuştur. Anketin yalnızca kulüp etkinliklerine katılanlara etkinlik çıkışında uygulandığı düşünülürse bu sonucun asıl kısıtı nedir?', 'Etkinliklere gelmeyen ve muhtemelen daha az memnun olan üyeler örneklemde yoktur', ['Soru açık uçlu biçimde sorulduğu için sonuç güvenilir sayılamaz', 'Etkinliklere katılanların büyük çoğunluğu soruyu yanlış anlamıştır', 'Sonuç %100 olmadığı için örneklem çok küçüktür'], 'Örneklem yalnızca etkinliğe katılmayı seçenlerden oluşur; memnun olmayanların etkinliklere gelmemesi olası olduğundan memnuniyet olduğundan yüksek görünür.'),
  ('Bir anket, katılımcılara \'Okulunuzdaki rehberlik servisinden memnun musunuz?\' sorusunu, önce \'Rehberlik servisine hiç gittiniz mi?\' sorusunu sormadan yöneltiyor. Bunun sonucu ne olabilir?', 'Kullanmamış kişiler de izlenime dayalı memnuniyet bildirebilir', ['Servisi kullanan kişiler soruyu hiçbir şekilde yanıtlayamaz', 'Sorunun yanıtları kendiliğinden daha güvenilir ve geçerli hâle gelir', 'Anketin toplam soru sayısı ve süresi yarıya iner'], 'Filtre sorusu olmadan deneyimi olmayanlar da izlenime dayalı yanıt verir; bu da gerçek kullanıcıların memnuniyetini ölçmeyi zorlaştırır.'),
  ('Bir anket yanıtlarında katılımcıların bir kısmının \'Bilmiyorum\' seçeneğini işaretlemesi neden değerli bir bilgidir?', 'Bilgisi olmayanları görüş bildirmeye zorlamadan ayırt etmeyi sağlar', ['Anketin tamamen başarısız olduğunu ve verilerin silinmesi gerektiğini gösterir', 'Bu katılımcıların tümünün soruyu bilerek yanlış yanıtladığını gösterir', 'Örneklemin evreni tam olarak temsil ettiğini kesin olarak kanıtlar'], 'Bilgi gerektiren konularda \'Bilmiyorum\' seçeneği yoksa katılımcılar uydurma görüşler bildirebilir; bu seçenek veri kalitesini korur.'),
  ('Anketlerde \'Son 12 ayda\' yerine \'Son 7 günde\' gibi kısa bir hatırlama süresi kullanılması özellikle hangi tür sorular için önerilir?', 'Sık yapılan gündelik davranışlara ilişkin sorular', ['Ömür boyu yalnızca bir kez yaşanan olaylara ilişkin sorular', 'Katılımcının doğum yerine ilişkin sorular', 'Katılımcının en son mezun olduğu okula ilişkin sorular'], 'Sık tekrarlanan davranışlar (ör. kaç bardak su içildiği) uzun dönemler için doğru hatırlanamaz; kısa dönem daha doğru sayı verir.'),
  ('Bir anket aynı konuda iki benzer soruyu farklı yerlerde soruyor ve araştırmacı iki yanıtın tutarlılığına bakıyor. Bu uygulamanın amacı nedir?', 'Dikkatsiz ya da tutarsız yanıt veren katılımcıları belirlemek', ['Anketin süresini kısaltmak ve gereksiz soruları çıkarmak', 'Katılımcıları birbirine zıt iki farklı görüşe zorlamak ve ikna etmek', 'Örneklem çerçevesindeki mükerrer kayıtları silmek'], 'Kontrol soruları, katılımcının soruları okuyup okumadığını ve tutarlı yanıt verip vermediğini sınamak için kullanılır.'),
  ('\'Okula başladığınız ilk günü anlatır mısınız?\' sorusu görüşme soruları sınıflamasında hangi türe girer?', 'Deneyim ve davranış sorusu', ['Demografik soru', 'Varsayımsal (hayali durum) sorusu', 'Kapalı uçlu soru'], 'Katılımcının yaşadığı bir olayı ve neler yaptığını anlatmasını isteyen sorular deneyim/davranış sorularıdır.'),
  ('Bir görüşmeci görüşme boyunca katılımcıyla göz teması kurmadan sürekli not alıyor. Bu davranışın olası etkisi nedir?', 'Katılımcının dinlenmediğini düşünüp daha az ayrıntı vermesi', ['Katılımcının çok daha rahat ve uzun ayrıntılı anlatımlarda bulunması', 'Görüşmenin kendiliğinden yapılandırılmış görüşmeye dönüşmesi', 'Görüşme verisinin daha nesnel ve daha güvenilir hâle gelmesi'], 'Not alma gereklidir ama göz teması ve ilgiyi gölgelememelidir; aksi hâlde etkileşim zayıflar. Bu yüzden kayıt cihazı sıklıkla tercih edilir.'),
  ('Çocuklarla yapılan görüşmelerde \'Öğretmen sana bağırdı mı?\' gibi bir sorunun özellikle sakıncalı olmasının nedeni nedir?', 'Çocuklar yetişkinin beklediğini düşündükleri yanıta yönelebilir', ['Çocukların soruları her zaman yetişkinlerden daha iyi anlaması', 'Sorunun açık uçlu olduğu için verilen yanıtların hiçbir biçimde kodlanamaması', 'Çocukların görüşmelere katılmasının her durumda yasak olması'], 'Çocuklar yönlendirici sorulara karşı daha duyarlıdır ve yetişkini memnun etmek isteyebilir; \'Bugün sınıfta neler oldu?\' gibi açık sorular tercih edilir.'),
  ('Görüşme dökümleri üzerinde araştırmacının tekrar eden fikirleri belirleyip bunları anlamlı gruplar altında toplamasına ne ad verilir?', 'Tematik çözümleme', ['Sistematik örnekleme', 'Pilot uygulama', 'Tabakalama'], 'Tematik çözümleme, nitel verideki örüntüleri (temaları) belirleme, düzenleme ve yorumlama sürecidir.'),
  ('İki araştırmacının aynı görüşme dökümlerini bağımsız olarak kodlayıp sonra kodlarını karşılaştırması hangi amaca hizmet eder?', 'Kodlamanın tek bir kişinin yorumuna bağlı kalmaması', ['Görüşme sayısını iki katına çıkarıp örneklemi büyütmek', 'Katılımcıların kimliklerini dökümlerde açıkça ortaya koymak', 'Görüşmelerin ses kayıtlarını silmeye gerek bırakmamak'], 'Bağımsız kodlama ve karşılaştırma, kodlamanın tutarlılığını ve inanılırlığını artırır; anlaşmazlıklar tartışılarak kod tanımları netleştirilir.'),
  ('Bir araştırmacının görüşme yapacağı kişileri seçerken yalnızca kendisiyle aynı görüşleri paylaştığını bildiği kişileri seçmesi hangi soruna yol açar?', 'Yalnızca araştırmacıyı doğrulayan tek yönlü bir tablo çıkması', ['Görüşmelerin hiç kayda alınamaması ve dökümünün yapılamaması', 'Katılımcı sayısının kendiliğinden ve çok hızlı biçimde artması', 'Görüşmelerin yapılandırılmış hâle gelip standartlaşması'], 'Seçim araştırmacının beklentisine göre yapılırsa farklı görüşler hiç duyulmaz; amaçlı örneklemede bile ölçütler açık ve gerekçeli olmalıdır.'),
  ('Görüşmeler sırasında bir katılımcı, kendisine ya da başkalarına ciddi zarar verme riski taşıyan bir durumdan söz ederse araştırmacının ne yapması beklenir?', 'Önceden belirlenmiş etik protokole göre uygun desteğe yönlendirmek', ['Gizlilik sözü verdiği için hiçbir şey yapmadan görüşmeye devam etmek', 'Bilgiyi araştırma raporunda katılımcının adıyla yayımlamak', 'Görüşmeyi kesip katılımcıyla bir daha hiç iletişim kurmamak'], 'Gizliliğin sınırları onam sürecinde açıklanmalıdır; ciddi zarar riski durumlarında araştırmacı etik kurulca onaylanan yönlendirme adımlarını izler.'),
  ('Görüşme yapılan kişilerin söylediklerini araştırmacının kendi beklentisine uygun biçimde seçip yorumlamasını azaltmak için aşağıdakilerden hangisi yararlıdır?', 'Aykırı ve çelişen örnekleri de raporda tartışmak', ['Yalnızca beklentiyi destekleyen alıntıları seçip raporlamak', 'Görüşme dökümlerini çözümlemeden önce silmek', 'Katılımcı sayısını bire indirerek derinleşmek'], 'Beklentiye uymayan (aykırı) durumların aranması ve tartışılması, yorumların tek yönlü olmasını engeller ve bulguların güvenilirliğini artırır.'),
  ('Bir odak grup görüşmesinde moderatörün yanında bulunan ve tartışmaya katılmadan konuşma sırasını, beden dilini ve önemli anları not eden kişiye ne ad verilir?', 'Raportör', ['Kilit (anahtar) bilgi verici', 'Anketör', 'Kodlayıcı'], 'Raportör, moderatörün tartışmayı yönetmeye odaklanabilmesi için ses kaydının yakalayamadığı ayrıntıları kaydeder.'),
  ('Odak grup görüşmesinde moderatörün kendi görüşlerini tartışmaya katmaktan kaçınması neden önemlidir?', 'Katılımcıların moderatörün görüşüne uyum gösterme olasılığı nedeniyle', ['Moderatörün konu hakkında hiçbir bilgisi olmadığı için', 'Odak gruplarda konuşmak yalnızca katılımcılara yasal olarak izin verildiği için', 'Moderatörün görüşleri her zaman yanlış olduğu için'], 'Moderatör otorite figürü olarak görülebilir; görüşünü açıklaması tartışmayı belirli bir yöne çekebilir.'),
  ('Bir ekolog bir çayırdaki papatya sayısını tahmin etmek için alanı eşit karelere bölüp rastgele seçtiği 30 karedeki papatyaları sayıyor. Bu yöntem hangi örnekleme mantığına dayanır?', 'Rastgele seçilen alan birimlerinden bütüne tahmin yürütme', ['Çayırdaki tüm papatyaların tek tek sayıldığı tam sayım', 'Araştırmacının en çiçekli kareleri bilerek seçtiği amaçlı örnekleme', 'Bulunan her papatyanın yeni bir papatyayı gösterdiği kartopu örneklemesi'], 'Alan birimleri (kareler) rastgele seçilir ve bu birimlerdeki sayım tüm alana genellenir; bu, alan birimleriyle yapılan olasılıklı bir örneklemedir.'),
  ('Bir ülkede istihdam ve işsizlik göstergelerinin her ay tüm haneler sayılmadan, seçilmiş örneklem hanelerle yapılan bir anketle hesaplanmasının temel gerekçesi nedir?', 'Her ay tam sayım yapmanın maliyeti ve süresi', ['Örneklemin her zaman tam sayımdan daha az hatalı olması', 'Hanelerin listesinin hiçbir zaman bilinmemesi', 'Tam sayımın yasal olarak yasaklanmış olması'], 'Sık tekrarlanan göstergeler için tam sayım pratik değildir; iyi tasarlanmış olasılıklı bir örneklem kabul edilebilir kesinlikte ve hızda sonuç verir.'),
  ('Bir kulübün 500 üyesinden 50\'si seçilecektir. Üyeler kulübe katılış tarihine göre listelenmiştir ve listede belirgin bir döngü yoktur. Hangi yöntem hem pratik hem de olasılıklı bir seçim sağlar?', 'Rastgele başlangıçlı sistematik örnekleme', ['Kulüp başkanının tanıdığı 50 üyeyi seçmesi', 'İlk gelen 50 üyenin seçilmesi', 'Üyelerin birbirini önermesiyle 50 kişiye ulaşılması'], 'Döngü olmayan bir listede rastgele başlangıçla her 10. üyeyi seçmek kolay uygulanır ve her üyeye eşit seçilme şansı verir.'),
  ('Bir araştırmacı 1.000 kişiye ulaşmak için bir çizelgede yaş ve cinsiyete göre hedef sayıları belirliyor; sonra anketörler bu sayıları doldurana kadar sokakta görüşme yapıyor. Bu yöntemin tabakalı örneklemeye göre avantajı ne olabilir?', 'Örneklem çerçevesi gerekmeden hızlı ve ucuz uygulanabilmesi', ['Her bireyin seçilme olasılığının kesin olarak hesaplanabilmesi', 'Görüşmecilerin seçim yanlılığının tamamen ortadan kalkması', 'Hata payının olasılık kuramıyla kesin biçimde hesaplanabilmesi'], 'Kota örneklemesi liste gerektirmez ve hızlıdır; ancak olasılıklı olmadığından hata payı kuramsal olarak hesaplanamaz.'),
  ('Bir siyaset bilimci, bir ülkedeki 20 ilin 4\'ünü \'parti tabanlarının en farklı olduğu iller\' gerekçesiyle seçip bu illerde odak grup yapıyor. İl seçimi hangi örnekleme mantığını yansıtır?', 'Amaçlı (maksimum çeşitlilik) örnekleme', ['Basit rastgele örnekleme', 'Sistematik örnekleme', 'Gönüllü yanıt (kendiliğinden seçim) örneklemesi'], 'İller rastgele değil, farklılığı en üst düzeye çıkarmak amacıyla bilinçli olarak seçilmiştir.'),
  ('Bir araştırmacı ülke genelinde temsil edici bir örneklem çekmiş, ancak sonuçları ayrıca yalnızca 45 kişinin düştüğü küçük bir bölge için de yorumlamak istiyor. Bu yorumun temel zayıflığı nedir?', 'Alt grup küçük olduğundan o bölgeye ait tahminin hata payı çok büyüktür', ['Küçük bölgede örnekleme hatası her zaman sıfırdır', 'Ülke örneklemi küçük bölgeleri her zaman ve kesinlikle dışarıda bırakır', '45 kişi tam sayım sayılır'], 'Ülke örneklemi içinde küçük alt gruplar az sayıda kişiyle temsil edilir; bu gruplara ait tahminler geniş belirsizlik taşır.'),
  ('Bir araştırmacı belirli bir olayı (ör. bir okuldaki başarılı bir kaynaştırma uygulamasını) derinlemesine anlamak istiyor ve yalnızca bu okulla çalışıyor. Bu çalışmada örneklem seçimi en iyi nasıl tanımlanır?', 'Araştırma amacına göre seçilmiş tek bir durum', ['Basit rastgele seçilmiş ve listeden kura ile belirlenmiş bir okul', 'Sistematik olarak seçilmiş okul listesi', 'Kota ile doldurulmuş bir öğrenci grubu'], 'Okul, amaca uygun bilgi zengini bir durum olarak bilinçli biçimde seçilmiştir; bu bir amaçlı seçim ve tek durumlu incelemedir.'),
  ('Ulaşılması zor bir grupta kartopu örneklemesinin yanlılığını azaltmak için önerilen önlemlerden biri hangisidir?', 'Zinciri farklı çevrelerden birden çok başlangıç kişisiyle başlatmak', ['Zinciri tek bir kişiden başlatıp yalnızca onun yakın arkadaşlarıyla sınırlamak', 'Her katılımcının yalnızca kendi ailesinden birini önermesine izin vermek', 'Zinciri olabildiğince kısa tutup ilk iki kişide bırakmak'], 'Farklı sosyal ağlardan başlayan birden çok zincir, örneklemin tek bir çevreye sıkışmasını engeller.'),
  ('Ankete katılan 1.000 kişiden 600\'ü kadın ve 400\'ü erkektir; oysa evrende kadın ve erkek oranları eşittir. Ağırlıklandırmada erkek katılımcıların ağırlığı kadınlarınkine göre nasıl olmalıdır?', 'Daha büyük', ['Daha küçük', 'Eşit', 'Sıfır'], 'Erkekler örneklemde az temsil edildiği için yanıtlarına daha büyük ağırlık verilir (0,5/0,4 = 1,25; kadınlar için 0,5/0,6 ≈ 0,83).'),
  ('Bir araştırmacı ankete katılım ödülünü yalnızca \'olumlu görüş bildirenlere\' vereceğini duyuruyor. Bu uygulamanın sorunu nedir?', 'Ödül yanıtların içeriğini çarpıtır', ['Ödül yanıt oranını her durumda düşürür', 'Ödül anketi yasal olarak geçersiz kılar', 'Ödül örneklemi kendiliğinden rastgele yapar'], 'Teşvik yanıtların içeriğine bağlanırsa katılımcılar ödülü almak için gerçek görüşlerini değiştirir; bu hem yöntemsel hem etik bir sorundur.'),
  ('Bilgisayar destekli anket uygulamalarının kâğıt ankete göre bir avantajı aşağıdakilerden hangisidir?', 'Filtre sorularındaki atlamaların otomatik ve hatasız yapılması', ['Anketörün görüşme sırasında hiçbir biçimde gerekmemesi', 'Yanıtların sonradan değiştirilememesi nedeniyle hatanın hiç oluşmaması', 'Katılımcıların yanıtlarının her zaman daha olumlu çıkması'], 'Yazılım, filtre yanıtına göre ilgili soruya kendiliğinden geçer ve geçersiz girişleri engeller; bu, veri girme ve atlama hatalarını azaltır.'),
  ('Bir anket verisinde \'18–24 yaş\' grubunda yer aldığını işaretleyen bir katılımcının \'emekli\' meslek seçeneğini de işaretlediği görülüyor. Veri temizleme açısından bu ne tür bir sorundur?', 'Mantıksal tutarsızlık', ['Kapsam hatası', 'Örnekleme aralığı hatası', 'Hale etkisi'], 'Birbiriyle çelişen yanıtlar (genç yaşta emeklilik gibi) tutarlılık denetimleriyle saptanır; veri girişi hatası ya da dikkatsiz yanıt olabilir.'),
  ('Bir çevrimiçi ankette 40 soruluk formu 90 saniyede bitiren katılımcıların yanıtları hakkında en makul değerlendirme hangisidir?', 'Soruları okumadan yanıtlamış olabilecekleri', ['En dikkatli ve en bilgili katılımcılar oldukları', 'Anketin çok uzun olduğunun kanıtlandığı', 'Örneklemin evreni temsil ettiği'], 'Gerçekçi olmayan kısa doldurma süreleri, dikkatsiz ya da rastgele yanıtlamanın göstergesidir ve veri kalitesi denetimlerinde dikkate alınır.'),
  ('Derecelendirme soruları yerine \'en önemli üç özelliği seçiniz\' biçiminde bir soru kullanmanın yararı nedir?', 'Katılımcıyı öncelik belirlemeye zorlayıp her şeye \'çok önemli\' dedirtmemek', ['Katılımcının tüm özellikleri eşit önemde ve aynı puanla göstermesini sağlamak', 'Sorunun yanıtlanmasını tamamen isteğe bağlı ve gereksiz hâle getirmek', 'Yanıtların sayısal olarak hiçbir biçimde çözümlenememesini sağlamak'], 'Derecelendirme sorularında katılımcılar her seçeneği yüksek puanlayabilir; seçim sınırlaması gerçek öncelikleri ortaya çıkarır.'),
  ('Bir ankette \'Ne kadar sıklıkla kütüphaneye gidersiniz?\' sorusunun seçenekleri \'Çok sık – Sık – Ara sıra – Nadiren\' biçimindedir. Bu seçeneklerin zayıflığı nedir?', 'Seçeneklerin anlamı kişiden kişiye değişebilir', ['Seçenekler birbirinden tamamen bağımsız iki konuyu ölçer', 'Seçenekler açık uçlu bir soruyu kapalı uçluya dönüştürür', 'Seçenekler yalnızca sayısal yanıtlara uygundur'], '\'Sık\' biri için haftada bir, başkası için ayda bir olabilir; \'Haftada birden fazla\', \'Ayda birkaç kez\' gibi somut sıklık seçenekleri daha karşılaştırılabilirdir.'),
  ('Bir öğretmen sınıfında \'Sınavlar sizi ne kadar kaygılandırıyor?\' sorusunu Likert ölçeğiyle soruyor. Ölçeğin her basamağına sözel etiket (ör. \'Hiç\', \'Biraz\', \'Orta\', \'Çok\', \'Aşırı\') konmasının yararı nedir?', 'Katılımcıların basamakları benzer biçimde yorumlamasını kolaylaştırmak', ['Ölçeğin yalnızca iki basamaktan oluşmasını ve sadeleşmesini sağlamak', 'Katılımcıların yanıt vermesini zorlaştırmak', 'Yanıtların kodlanmasını imkânsız kılmak'], 'Yalnızca uç noktaları etiketli ölçeklerde ara basamaklar farklı yorumlanabilir; her basamağa etiket vermek anlam birliği sağlar.'),
  ('Bir anketi çevrimiçi uygularken her soruyu zorunlu yanıtlı yapmanın olası olumsuz sonucu nedir?', 'Rastgele işaretleme ya da anketi yarıda bırakma', ['Tüm yanıtların kesinlikle daha doğru ve dürüst olması', 'Madde yanıtsızlığının veri kalitesini her zaman artırması', 'Anket süresinin kendiliğinden yarıya inmesi'], 'Zorunlu sorular boş bırakmayı engeller ama istemeyen katılımcıyı rastgele yanıt vermeye ya da anketten çıkmaya iter; \'Yanıtlamak istemiyorum\' seçeneği bir çözüm olabilir.'),
  ('Bir anketin sonuçları raporlanırken yanıt oranının da belirtilmesi neden önemlidir?', 'Okurun yanıtsızlık kaynaklı yanlılık riskini değerlendirebilmesi için', ['Anketin kaç sayfa olduğunu göstermek için', 'Katılımcıların adlarını açıklamak için', 'Hata payını tamamen ortadan kaldırıp sıfıra indirmek için'], 'Düşük yanıt oranı tek başına sonucu geçersiz kılmaz ama yanlılık olasılığını artırır; okur bu bilgiyle sonucu daha bilinçli yorumlar.'),
  ('Bir müzede hangi sergilerin daha çok ilgi gördüğünü anlamak için sergilerin önündeki zemin karolarının aşınma ve değiştirilme sıklığının incelenmesi hangi tür ölçüme örnektir?', 'Tepkisel olmayan (iz) ölçüm', ['Yapılandırılmış görüşme', 'Likert tipi tutum ölçümü', 'Odak grup tartışması'], 'İz ölçümleri, insanların davranışlarının bıraktığı fiziksel izleri inceler; kişiler ölçüldüklerini bilmediği için tepkisellik yoktur.'),
  ('Bir kentte geri dönüşüm alışkanlığını anlamak için hane anketleri yerine çöp kutularındaki atıkların incelenmesinin üstünlüğü nedir?', 'Kişilerin beyanına değil gerçek davranışın izine dayanması', ['Kişilerin düşüncelerini ve duygularını doğrudan göstermesi', 'Hiçbir etik değerlendirme gerektirmemesi', 'Her zaman anketten daha ucuz ve hızlı olması'], 'Atık incelemesi beyan edilen değil gerçekleşen davranışı yansıtır; yine de mahremiyet açısından değerlendirme gerektirir.'),
  ('Tepkisel olmayan ölçümlerin genel bir sınırlılığı aşağıdakilerden hangisidir?', 'İzin kimin davranışından kaynaklandığının ya da nedeninin her zaman bilinememesi', ['Katılımcıların gözlemcinin varlığından büyük ölçüde etkilenmesi', 'Katılımcıların her zaman yanıltıcı ve abartılı yanıtlar vermesi', 'Verilerin yalnızca görüşmelerle toplanabilmesi'], 'Bir iz (ör. aşınma) birçok nedene bağlı olabilir ve tek tek kişilerin özellikleri bilinmez; bu, yorumu sınırlar.'),
  ('Bir çocuk bir ders boyunca iki kez sırasından kalkıyor; ancak bir seferinde 25 dakika ayakta kalıyor. Yalnızca sıklık kaydı kullanılmasının sakıncası nedir?', 'Davranışın yoğunluğunu ve süresini gizlemesi', ['Davranışın hiç kaydedilmemesi', 'Gözlemci etkisini artırması', 'Gözlemciler arası uyumu imkânsız kılması'], 'İki kez kalkma az görünür, ama 25 dakika ayakta kalmak önemli bir sorundur; uzun süren davranışlarda süre kaydı daha anlamlıdır.'),
  ('Bir araştırmacı ormanda bir tilkinin günlük etkinliklerini kaydetmek için her 10 dakikada bir o anda ne yaptığını (dinleniyor, avlanıyor, yürüyor) not ediyor. 6 saatlik gözlemde \'dinleniyor\' 18 kez kaydedilmişse, gözlem anlarının yüzde kaçında hayvan dinlenmektedir?', '%50', ['%30', '%18', '%60'], '6 saat × 6 kayıt/saat = 36 gözlem anı. 18/36 = %50.'),
  ('Bir araştırmacının yeni bir ortamda gözleme başlamadan önce ortamın krokisini çizip kimin nerede durduğunu not etmesi hangi amaca hizmet eder?', 'Mekânsal bağlamın davranışları nasıl etkilediğini anlamak', ['Katılımcıların kimliklerini kesin olarak belirlemek', 'Gözlemi gizli hâle getirmek', 'Örneklem büyüklüğünü hesaplamak'], 'Mekânın düzeni (masaların yeri, girişler) etkileşimleri etkiler; kroki, alan notlarının bağlamını zenginleştirir.'),
  ('Bir araştırmacının bir köy düğününe davet edilip törenin her aşamasını izlemesi ve aynı zamanda oyunlara katılması, alan çalışmasında hangi ilkeye dikkat etmesini gerektirir?', 'Katılım ile gözlem arasında dengeyi korumak', ['Hiçbir koşulda not almamak', 'Köylülere yalnızca kapalı uçlu sorular sormak', 'Düğünü kendi istediği biçimde yönlendirmek'], 'Katılım anlamayı derinleştirir ama aşırı katılım gözlemi zorlaştırır ve olayları etkileyebilir; araştırmacı iki rol arasında denge kurar.'),
  ('Bir araştırmacının çalıştığı topluluğun dilini öğrenmesinin etnografik çalışmaya katkısı nedir?', 'Tercüman olmadan anlamları ve gündelik konuşmaları doğrudan anlayabilmek', ['Örneklem büyüklüğünü kendiliğinden ve hızla artırmak', 'Gözlem yerine yalnızca anket kullanabilmek', 'Topluluğun davranışlarını değiştirmek ve yönlendirmek'], 'Dil, kültürel anlamların taşıyıcısıdır; yerel dili bilmek aracı çevirinin getirdiği anlam kayıplarını ortadan kaldırır.'),
  ('Bir antropolog incelediği köyden ayrıldıktan sonra, yazdığı etnografide köyün gerçek adını kullanmamaya karar veriyor. Bu kararın temel gerekçesi nedir?', 'Topluluk üyelerinin tanınmasını ve zarar görmesini önlemek', ['Okurların köyü kolayca bulmasını sağlamak', 'Kitabın daha kısa olmasını sağlamak', 'Örnekleme hatasını azaltmak'], 'Küçük toplulukların açıkça adlandırılması, içerdeki bilgilerin kimlerle ilişkilendirileceğini kolaylaştırır; takma ad kullanımı yaygın bir gizlilik önlemidir.'),
  ('Bir araştırmacının gözlem sırasında gözlenen kişilerin konuşmalarını kelimesi kelimesine aktarmak için not defterine tırnak içinde yazması neyi amaçlar?', 'Doğrudan aktarılan sözleri araştırmacının özetlerinden ayırmayı', ['Notların daha süslü görünmesini', 'Katılımcıların kimliklerini belirtmeyi', 'Gözlemin süresini kısaltmayı'], 'Tırnak işaretleri, notlarda katılımcının kendi ifadesiyle araştırmacının özetinin karışmasını önler.'),
  ('Bir araştırmacının uzun süreli bir alan çalışmasında her gün sonunda tuttuğu ve kendi duygularını, kararlarını ve yöntemsel sorunları yazdığı defterin işlevi nedir?', 'Araştırma sürecini ve araştırmacının etkisini belgelemek', ['Katılımcıların kimliklerini kamuya açıklamak', 'Gözlem verilerinin yerine geçmek', 'Örneklemi büyütmek'], 'Araştırma günlüğü, kararların gerekçelerini ve araştırmacının konumunu kayda geçirerek düşünümselliği ve şeffaflığı destekler.'),
  ('Bir kota planında 250 kişilik örneklemin %20\'sinin 65 yaş üstü olması isteniyor. Anketörler 65 yaş üstü 38 kişiyle görüşmüştür. Kotanın dolması için kaç kişiyle daha görüşülmelidir?', '12', ['50', '38', '62'], 'Kota 250 × 0,20 = 50 kişidir. 50 − 38 = 12 kişi daha gerekir.'),
  ('Aynı kişilere 2018, 2020 ve 2022 yıllarında sağlık alışkanlıkları sorulmuş; 2018\'de 1.000 olan katılımcı sayısı 2022\'de 720\'ye düşmüştür. Bu dönemdeki katılımcı kaybı yüzde kaçtır?', '%28', ['%72', '%38', '%22'], 'Kayıp 1.000 − 720 = 280 kişidir; 280/1.000 = %28.'),
  ('Bir araştırmacı kentteki 50 eczaneden 5\'ini rastgele seçiyor ve bu eczanelere bir gün boyunca gelen tüm müşterilere anket uyguluyor. Bu tasarımda rastgele seçimin yapıldığı birim hangisidir?', 'Satış noktaları', ['Tek tek müşteriler', 'Kentin tamamı', 'Satılan ürünler'], 'Rastgele seçilen birimler eczanelerdir; müşteriler seçilen kümelerin içinden toplu olarak alınır. Bu bir küme örneklemesidir.'),
  ('\'Türkiye Büyük Millet Meclisi hangi yıl açılmıştır?\' gibi bir sorunun bir tutum anketine eklenmesinin amacı ne olabilir?', 'Katılımcıların siyasi bilgi düzeyini ölçmek', ['Katılımcıların mutluluk düzeyini ölçmek', 'Katılımcıların yaşını ve doğum yılını öğrenmek', 'Katılımcıların onamını almak'], 'Bilgi soruları katılımcının bir konudaki olgusal bilgisini ölçer ve tutumların bilgi düzeyine göre karşılaştırılmasına olanak verir.'),
  ('Bir anket bir gençlik merkezinin kullanımını ölçerken \'Merkezi ne sıklıkla kullanırsınız?\' sorusunu \'Merkezden memnun musunuz?\' sorusundan önce soruyor. Bu sıralamanın genel mantığı nedir?', 'Olgusal ve davranışsal sorulardan değerlendirme sorularına geçmek', ['Değerlendirme sorularını en başa alıp katılımcıyı yönlendirmek', 'Hassas soruları güven oluşmadan anketin başına yerleştirmek', 'Soruları alfabetik sıraya dizmek'], 'Davranışla başlamak katılımcıyı somut deneyimine yönlendirir; memnuniyet değerlendirmesi bu deneyime dayanarak daha anlamlı yapılır.'),
  ('Bir belediye, park kullanıcılarının parkta ne kadar süre kaldığını öğrenmek için \'Parkta genellikle ne kadar vakit geçirirsiniz?\' diye soran bir anket yapıyor; bir başka ekip ise giriş ve çıkış saatlerini gözlemle kaydediyor. İki sonuç farklı çıkarsa hangisi süre konusunda daha doğrudan kanıttır?', 'Gözlemle kaydedilen giriş-çıkış saatleri', ['Anketteki \'genellikle\' biçiminde verilen tahmini yanıtlar', 'İki sonucun ortalaması', 'Hangisinin daha büyük çıktığı'], 'Süre gözlenebilir bir davranıştır; doğrudan kayıt, kişilerin tahminlerine ve hatırlama hatalarına dayanan beyandan daha doğrudan kanıttır.'),
  ('Bir şirket yeni bir mobil uygulamanın kullanıcılar tarafından nasıl kullanıldığını öğrenmek istiyor. Kullanıcıların uygulamayı kullanırken düşündüklerini sesli söylemeleri ve ekranlarının izlenmesi hangi iki yöntemi birleştirir?', 'Gözlem ve sözlü anlatıma dayalı görüşme', ['Tabakalı örnekleme ve kota örneklemesi', 'Posta anketi ve doküman incelemesi', 'Delphi tekniği ve sözlü tarih'], 'Ekranın izlenmesi davranışın gözlenmesidir; sesli düşünme ise katılımcının o anki düşüncelerini sözlü olarak aktarmasını sağlar.'),
  ('Bir lisede öğrencilerin okul kantinindeki besin tercihlerini belirlemek isteyen bir öğrenci kulübü için en az yanlı ve en pratik veri kaynağı hangisidir?', 'Kantinin satış kayıtları', ['Kulüp üyelerinin kendi tahminleri', 'Kantinci ile tek bir görüşme', 'Okulun sosyal medya anketi'], 'Satış kayıtları gerçekleşen tüm satışları kapsar ve tepkisel değildir; tahminler, tek görüşme ve gönüllü anket daha yanlıdır.'),
  ('Bir araştırmacı yaşlı bakım evlerinde yaşayan kişilerin günlük yaşamlarını anlamak istiyor; katılımcıların bir kısmı bilişsel güçlükler yaşıyor. Hangi yöntem bileşimi en uygundur?', 'Gözlem ile birlikte kısa, sade görüşmeler ve bakıcılarla görüşme', ['Yalnızca uzun, ayrıntılı ve karmaşık sorular içeren yazılı anketler', 'Yalnızca çevrimiçi anket formu', 'Yalnızca telefonla yapılandırılmış görüşme'], 'Bilişsel güçlükler yazılı ve uzun yöntemleri zorlaştırır; gözlem, sade görüşmeler ve bakıcıların bakışı birlikte daha bütüncül bir resim verir.'),
  ('Bir araştırmacı bir okulda \'Ödevlerini kimden yardım alarak yaparsın?\' sorusunu açık uçlu olarak sormuştur. Yanıtlar \'annem\', \'ablam\', \'internet\', \'arkadaşım\', \'kimse\' gibi çeşitlidir. Bu yanıtları çözümlemenin ilk adımı ne olmalıdır?', 'Yanıtları anlamlı kategorilere ayıracak bir kod listesi oluşturmak', ['Yanıtları rastgele silip örneklemi küçültmek', 'Yanıtların tümünü tek bir \'aile\' kategorisine alıp diğerlerini göz ardı etmek', 'Soruyu çözümlemeden rapordan çıkarmak'], 'Açık uçlu yanıtlar önce aile, akran, dijital kaynak, yardımsız gibi kategorilerle kodlanır; ardından sıklıklar hesaplanabilir.'),
  ('Bir görüşmeci, katılımcının ilk yanıtı \'Bilmiyorum\' olduğunda hemen bir sonraki soruya geçiyor. Bu davranışın olası sonucu nedir?', 'Katılımcının biraz düşündükten sonra verebileceği bilgilerin kaybolması', ['Görüşmenin daha nesnel hâle gelmesi', 'Görüşmeci etkisinin tamamen ve kesin olarak ortadan kalkması ve verinin arınması', 'Katılımcının onamının geçersiz sayılması'], '\'Bilmiyorum\' bazen düşünmek için zaman kazanma biçimidir; nazik bir bekleme ya da sondaj (\'Aklınıza gelen herhangi bir şey olabilir\') ek bilgi sağlayabilir.'),
  ('Bir araştırmacı köy kadınlarının tarımsal üretimdeki rolünü incelemek için yalnızca erkek muhtarlarla görüşüyor. Bu tasarımın temel zayıflığı nedir?', 'Kadınların kendi deneyimleri doğrudan dinlenmemiştir', ['Muhtarların köyleri hiç tanımaması', 'Görüşmelerin yapılandırılmamış olması', 'Örneklemin çok büyük olması'], 'Bir grubun deneyimi, o grubun kendisi dinlenmeden yalnızca başkalarının aktarımıyla incelenirse eksik ve yanlı bir tablo ortaya çıkabilir.'),
  ('Bir öğrenci okul gazetesi için \'öğrencilerin okul yemekleri hakkındaki görüşleri\' haberi hazırlıyor ve yemekhane kapısında yemek yiyen 20 öğrenciyle konuşuyor. Haberde hangi ifade yöntemle en uyumludur?', '\'Görüştüğümüz 20 öğrencinin çoğu yemeklerden memnun olduğunu söyledi\'', ['\'Okulun tüm öğrencileri yemeklerden memnun\'', '\'Öğrencilerin %85\'i okul yemeklerinden kesinlikle ve tamamen memnun\'', '\'Okulda yemeklerden şikâyet eden kimse yok\''], 'Kolay ulaşılabilir küçük bir örneklemle konuşulduğunda, sonuç yalnızca görüşülenler için ve sınırlılığıyla birlikte aktarılmalıdır.'),
  ('Bir öğrenci bilim projesi için kendi apartmanındaki 12 daireye kapı kapı gidip \'Su tasarrufu yapıyor musunuz?\' diye soruyor ve 11 dairenin \'evet\' dediğini buluyor. Bu sonucu yorumlarken hangi iki sorun birlikte dikkate alınmalıdır?', 'Küçük ve yerel örneklem ile sosyal beğenirlik', ['Gözlemciler arası uyum ile kota planının yanlış hazırlanması', 'Panel koşullanması ile katılımcı kaybı', 'Geri çeviri ile çift veri girişi'], 'Tek apartman genellenebilir değildir; ayrıca su tasarrufu toplumca onaylanan bir davranış olduğu için yüz yüze sorulduğunda abartılabilir.'),
  ('Evrenin tamamına ait sayısal bir özelliğe (ör. tüm öğrencilerin gerçek ortalama boyu) \'parametre\' denir. Örneklemden hesaplanan karşılığına ne ad verilir?', 'İstatistik', ['Tabaka', 'Örneklem çerçevesi', 'Kota'], 'Örneklemden hesaplanan değerler istatistiktir ve evren parametresini tahmin etmek için kullanılır.'),
  ('Günlük dilde \'rastgele\' sözcüğü gelişigüzel anlamında kullanılır. Araştırma yöntemlerinde rastgele seçim ile gelişigüzel seçim arasındaki fark nedir?', 'Rastgele seçimde her birimin seçilme olasılığı bilinir; gelişigüzel seçimde bilinmez', ['İkisi tamamen aynı anlama gelir ve araştırmada birbirinin yerine kullanılabilir', 'Gelişigüzel seçim her zaman daha temsil edicidir', 'Rastgele seçim yalnızca nitel araştırmalarda kullanılır'], 'Bilimsel anlamda rastgele seçim kura ya da rastgele sayılar gibi bir olasılık mekanizmasına dayanır; aklına geleni seçmek ise insan tercihinden etkilenir.'),
  ('\'Örneklem her zaman evrenin en az %10\'u olmalıdır\' görüşü neden yanlıştır?', 'Gerekli örneklem büyüklüğü evren oranından çok istenen kesinliğe bağlıdır', ['Örneklem evrenin her zaman en az yarısı kadar olmalı, daha azı yetersiz kalır', 'Örneklem büyüklüğü hiçbir koşulda hesaplanamaz', 'Evren büyüdükçe örneklem büyüklüğü her zaman orantılı artmalıdır'], 'Büyük evrenlerde %10 gereğinden çok büyük, küçük evrenlerde ise yetersiz olabilir; belirleyici olan hata payı, güven düzeyi ve değişkenliktir.'),
  ('Sabit hat telefonu rehberine dayanan anketlerin 2000\'lerden sonra giderek daha sorunlu hâle gelmesinin temel nedeni nedir?', 'Pek çok hanenin yalnızca cep telefonu kullanmaya başlaması', ['Telefonla anket yapmanın yasaklanması', 'Telefon rehberlerinin basılmasının ve dağıtılmasının yasal olarak yasaklanması', 'İnsanların telefonla konuşmayı tamamen bırakması'], 'Yalnızca cep telefonu kullananlar, özellikle gençler, sabit hat çerçevesinin dışında kalır; bu da kapsam hatasını büyütür.'),
  ('Bir öğrenci anketini okulun e-posta listesine gönderiyor; ancak listedeki adreslerin %30\'u artık kullanılmıyor. Bu durum hangi iki sorunu birlikte doğurur?', 'Çerçeve hatası ve buna bağlı yanıtsızlık', ['Görüşmeci etkisi ve hale etkisi', 'Panel koşullanması ve kota planının yanlış hazırlanması', 'Geri çeviri ve madde yanıtsızlığı'], 'Kullanılmayan adresler çerçevenin güncel olmadığını gösterir; bu adreslere ulaşılamadığı için de gerçek yanıt oranı düşer.'),
  ('Bir odak grup çalışmasında farklı kesimlerin (ör. öğrenciler, veliler, öğretmenler) ayrı gruplarda toplanması hangi amaca hizmet eder?', 'Her kesimin kendi bakışını daha rahat dile getirmesini sağlamak', ['Kesimlerin birbirini ikna etmesini ve tek görüşte birleşmesini sağlamak', 'Katılımcı sayısını gruplarda azaltıp moderatörü gereksiz kılmak', 'Sonuçları doğrudan evrene genellemek ve oranlar hesaplamak'], 'Güç ilişkileri olan kesimler aynı grupta olduğunda bazıları susabilir; ayrı gruplar her kesimin görüşlerini daha özgürce ortaya koyar ve karşılaştırma yapılabilir.'),
  ('Delphi çalışmasında bir uzmanın ikinci turda, grubun genel eğilimini gördükten sonra görüşünü değiştirmesi tekniğin hangi özelliğinin sonucudur?', 'Kontrollü geri bildirim', ['Gizli (bildirilmeyen) gözlem', 'Kota örneklemesi', 'Panel koşullanması'], 'Her turda grubun özet yanıtlarının uzmanlara geri bildirilmesi, uzmanların görüşlerini yeniden düşünmesini sağlar; uzlaşı bu süreçle aranır.'),
  ('Bir görüşmecinin \'Neden bu kadar az ders çalışıyorsun?\' sorusu yerine \'Ders çalışma düzenini anlatır mısın?\' sorusunu tercih etmesinin nedeni nedir?', 'İlk soru yargılayıcıdır ve katılımcıyı savunmaya iter', ['İlk soru çok uzundur ve katılımcılar tarafından kolayca anlaşılmaz', 'İkinci soru kapalı uçludur ve kolay kodlanır', 'İlk soru demografik bir sorudur'], '\'Neden\' ile başlayan ve varsayım içeren sorular suçlayıcı algılanabilir; betimleme isteyen sorular daha açık ve tarafsız yanıtlar getirir.'),
  ('Bir araştırmacı 12 kişiyle görüşmüş ve raporunda \'Katılımcıların %58,3\'ü...\' gibi yüzdeler kullanmıştır. Bu sunum biçimi hakkında en makul değerlendirme hangisidir?', 'Küçük örneklemde ayrıntılı yüzdeler yanlış bir kesinlik izlenimi verir', ['Yüzdeler 12 kişilik örneklemde evren oranını kesin olarak gösterir', 'Nitel araştırmalarda hiçbir sayı kesinlikle kullanılamaz', 'Yüzdeler katılımcıların kimliklerini açığa çıkarır'], '12 kişide %58,3 yalnızca 7 kişidir; ondalıklı yüzdeler genellenebilir bir ölçüm izlenimi yaratabilir. \'12 katılımcıdan 7\'si\' biçimi daha uygundur.'),
  ('Bir anket araştırmasında 18 yaşından küçükler evrenin parçası değildir. Anketin başına \'Kaç yaşındasınız?\' sorusunu koyup 18 yaşından küçükleri anketten çıkarmaya ne ad verilir?', 'Uygunluk taraması', ['Kota denetimi', 'Sondaj sorusu', 'Geri çeviri'], 'Uygunluk taraması (eleme sorusu), yalnızca evrenin tanımına uyan kişilerin anketin devamına geçmesini sağlar.'),
  ('Bir anketin uygulandığı dönemde ülke gündemini derinden etkileyen bir olay yaşanmışsa, bu durum sonuçların yorumlanmasında neden dikkate alınmalıdır?', 'Yanıtlar o döneme özgü geçici bir etkiyi yansıtabilir', ['Anketin tamamen geçersiz sayılması yasal bir zorunluluktur', 'Olaylar anket sonuçlarını hiçbir zaman etkilemez', 'Örneklem kendiliğinden tam sayıma dönüşür'], 'Kesitsel anketler bir anın fotoğrafıdır; olağan dışı olaylar tutumları geçici olarak değiştirebilir, bu yüzden uygulama tarihi raporlanır.'),
  ('Bir anketin pilot uygulamasında ortalama doldurma süresinin 35 dakika çıktığı, hedefin ise 15 dakika olduğu görülüyor. En uygun düzenleme hangisidir?', 'Araştırma sorusuyla doğrudan ilgili olmayan soruları çıkarmak', ['Katılımcılara soruları daha hızlı okumalarını ve kısa yanıt vermelerini söylemek', 'Soruların puntosunu küçültüp sayfaya sığdırmak', 'Örneklem büyüklüğünü iki katına çıkarmak'], 'Anket uzunluğunu azaltmanın doğru yolu, her sorunun araştırma amacına katkısını sorgulayıp gereksiz olanları çıkarmaktır.'),
  ('Bir çocuk psikoloğu, çocukların oyuncak tercihlerini incelerken her çocuğa aynı altı oyuncağın sunulduğu bir oyun odası hazırlıyor. Bu düzenlemenin doğal ortam gözlemine göre üstünlüğü nedir?', 'Tüm çocukların aynı seçeneklerle karşılaşması ve karşılaştırmanın kolaylaşması', ['Çocukların evdeki gerçek davranışlarını birebir, eksiksiz ve doğal biçimde yansıtması', 'Çocukların gözlendiklerini hiçbir biçimde fark etmemesi', 'Oyuncak tercihinin yaşla birlikte değişmesinin önlenmesi'], 'Kontrollü ortam, koşulları standart tutarak çocuklar arasında adil karşılaştırma sağlar; ancak ev ortamındaki doğal davranıştan farklı olabilir.'),
  ('Bir araştırmacı bir ilçedeki tüm muhtarlardan oluşan 45 kişilik bir grubun tamamına anket uyguluyor. Bu çalışmada örnekleme hatası hakkında ne söylenebilir?', 'Evrenin tamamı incelendiği için örnekleme hatası yoktur', ['Örnekleme hatası çok yüksektir', 'Örnekleme hatası yalnızca muhtar sayısına bölünerek bulunur', 'Örnekleme hatası her zaman ±5 puandır'], 'Evrenin tümüne ulaşıldığında (tam sayım) örnekleme hatası söz konusu değildir; ancak yanıtsızlık ve ölçme hataları yine de olabilir.'),
  ('Bir araştırmacı 1.000 kişilik bir örneklemde yanıt verenlerin eğitim düzeyinin evrenden belirgin biçimde yüksek olduğunu fark ediyor. Bu bulgu öncelikle neyi gösterir?', 'Yanıtsızlığın eğitim düzeyiyle ilişkili olabileceğini', ['Örneklemin evreni kusursuz temsil ettiğini', 'Eğitim düzeyinin anket yanıtları üzerinde hiçbir etkisi olmadığını', 'Hata payının sıfır olduğunu'], 'Yanıt verenlerin bilinen özellikleri evrenden farklıysa, yanıtsızlık rastgele değildir; ağırlıklandırma ve sonuçların dikkatli yorumu gerekir.'),
  ('Bir öğretmen öğrencilerine bir hafta boyunca her akşam ne kadar süre kitap okuduklarını not etmelerini istiyor. Bu veri toplama aracının temel riski nedir?', 'Öğrencilerin notları sonradan toplu doldurup tahmin yazması', ['Verinin hiçbir zaman sayısal biçimde toplanamaması', 'Öğrencilerin her gün aynı kitabı okumaya zorlanması', 'Gözlemcinin öğrencilerin evlerine gitmek zorunda kalması'], 'Günlükler düzenli tutulmazsa son gün toplu doldurulabilir; bu da günlüğün asıl üstünlüğü olan anlık kaydı ortadan kaldırır.'),
  ('Bir anket çalışmasında aynı kişinin birden fazla kez çevrimiçi formu doldurmasını önlemek için alınabilecek önlemlerden biri hangisidir?', 'Her katılımcıya yalnızca bir kez kullanılabilen kişisel bağlantı göndermek', ['Formu herkese açık sosyal medya sayfasında paylaşmak', 'Formun doldurulmasına karşılık katılımcılara her seferinde yeni bir ödül vermek', 'Formun doldurulma süresini uzatmak'], 'Tek kullanımlık bağlantılar mükerrer yanıtları engeller; açık paylaşım ve ödüller ise çoklu doldurmayı kolaylaştırabilir.'),
  ('Bir araştırmacı lise öğrencilerine ruh sağlığına ilişkin hassas sorular içeren bir anket uygulayacaktır. Anketin sonunda öğrencilere destek alabilecekleri kurumların iletişim bilgilerinin verilmesi hangi etik ilkeyle ilgilidir?', 'Katılımcılara zarar vermeme ve onları koruma', ['Örneklemin temsil ediciliği', 'Seçeneklerin karşılıklı dışlayıcılığı ve kapsayıcılığı', 'Gözlemciler arası uyum'], 'Hassas konular katılımcılarda sıkıntı uyandırabilir; destek kaynaklarının sunulması zarar riskini azaltan bir korumadır.'),
  ('Bir araştırmacı, bir derneğin üyelerine anket uygulamak için dernek başkanından izin alıyor ve üyelere \'Başkanınız bu ankete katılmanızı istiyor\' diye yazıyor. Bu ifadenin sorunu nedir?', 'Gönüllülüğü zedeleyen bir baskı algısı yaratması', ['Anketin süresini kesin olarak uzatması ve katılımcıları yorması', 'Seçeneklerin çakışmasına yol açması', 'Örneklem çerçevesini güncellemesi'], 'Otorite figürünün isteği olarak sunulan davet, üyelerin katılmamayı bir seçenek olarak görmesini zorlaştırır; davet tarafsız ve gönüllü vurgulu olmalıdır.'),
  ('Bir gözlemcinin derecelendirme ölçeğinde gözlediği herkese ölçeğin olumlu ucuna yakın yüksek puanlar vermesine ne ad verilir?', 'Cömertlik (hoşgörü) hatası', ['Merkezî eğilim hatası', 'Katılık (sertlik) hatası', 'Kapsam hatası'], 'Cömertlik hatasında gözlemci herkesi olduğundan olumlu değerlendirir; katılık hatası ise bunun tersidir.'),
  ('Bir anaokulu öğretmeninin çocukların gelişimini izlerken kontrol listesi, anekdot kayıtları ve çocukların çalışma örneklerini bir dosyada toplamasının yararı nedir?', 'Gelişimin birden çok kanıta dayalı ve bütüncül biçimde izlenmesi', ['Çocukların tek bir sınav puanıyla değerlendirilmesi', 'Gözlem yapmaya hiç gerek kalmaması', 'Ailelerin ve diğer öğretmenlerin görüşlerinin tamamen dışlanması'], 'Farklı türden kayıtların bir araya getirilmesi, tek bir aracın sınırlılığını dengeler ve gelişimin daha zengin bir resmini verir.'),
  ('Yapılandırılmamış bir görüşmede görüşmecinin \'Bana biraz kendinizden bahseder misiniz?\' gibi geniş bir soruyla başlamasının amacı nedir?', 'Katılımcının önemli bulduğu konuları kendi seçmesine alan tanımak', ['Katılımcının yalnızca evet ya da hayır demesini sağlamak', 'Görüşmeyi beş dakikada bitirmek', 'Katılımcıyı belirli bir yanıta ve görüşe doğru yönlendirmek'], 'Geniş açılış soruları, görüşmenin gündemini katılımcının belirlemesine izin verir ve araştırmacının öngörmediği konuların ortaya çıkmasını sağlar.'),
  ('Bir araştırmacı bir köyün tarihini yazmak için yaşlı bir kadının yaşam öyküsünü dinliyor. Bu anlatının bir \'kişisel belge\' olarak değeri nedir?', 'Resmî kayıtlarda olmayan gündelik yaşam deneyimini görünür kılması', ['Tüm köy halkının görüşünü istatistiksel olarak temsil etmesi', 'Olayların tarihlerini her zaman resmî belgelerden daha kesin vermesi', 'Araştırmacının hiçbir yorum yapmasına gerek bırakmaması'], 'Yaşam öyküleri bir kişinin bakış açısından gündelik yaşamı aktarır; temsil edici ya da tarihsel olarak her zaman kesin değildir, ama başka kaynaklarda olmayan bir derinlik sunar.'),
  ('\'Sınav sonucunu öğrendiğinizde neler hissettiniz?\' sorusu görüşme soruları sınıflamasında hangi türe girer?', 'Duygu sorusu', ['Bilgi sorusu', 'Demografik soru', 'Duyusal soru'], 'Duygu soruları katılımcının bir deneyime verdiği duygusal tepkileri öğrenmeye yöneliktir; bilgi soruları ise olgusal bilgiyi ölçer.'),
  ('Bir araştırmacı bir okulun 1950\'li yıllardaki disiplin anlayışını incelemek için okulun arşivindeki disiplin kurulu kararlarını okuyor. Bu belgelerin araştırmacıya sunduğu bilgi hangi açıdan sınırlı olabilir?', 'Belgeler yalnızca resmî sürece yansıyan olayları kaydetmiştir', ['Belgeler araştırmacının varlığından etkilenmiştir', 'Belgeler araştırma sorusuna göre ve araştırmacı için özel olarak üretilmiştir', 'Belgeler her zaman tamamen yansız ve eksiksizdir'], 'Kurum belgeleri kurulun ele aldığı olayları ve kurumun bakışını yansıtır; resmî sürece taşınmayan gündelik uygulamalar ve öğrencilerin görüşleri bu belgelerde görünmeyebilir.'),
  ('Bir anketin \'betimsel\' amaçlı olması ne anlama gelir?', 'Bir topluluğun özelliklerini ya da görüş dağılımını ortaya koyması', ['Nedensel ilişkileri kesin olarak kanıtlamayı amaçlaması', 'Yalnızca tek bir kişinin yaşam öyküsünü anlatması', 'Katılımcıları belirli bir görüşe ikna etmeyi amaçlaması'], 'Betimsel anketler \'ne kadar, kaç kişi, hangi oranda\' sorularını yanıtlar; örneğin bir ilçedeki hanelerin internet erişim oranını belirlemek.'),
  ('Bir hastanede hasta-hekim iletişimini incelemek isteyen bir araştırmacı, muayene odasında ses kaydı almak yerine bekleme salonunda gözlem yapmaya karar veriyor. Bu tercihin en olası gerekçesi nedir?', 'Muayene odasının yüksek mahremiyet taşıyan bir ortam olması', ['Bekleme salonunda hiç insan bulunmaması', 'Muayene odasında gözlem yapmanın her zaman daha ucuz olması', 'Bekleme salonunun laboratuvar ortamı olması'], 'Muayene sırasında sağlık bilgileri konuşulur ve mahremiyet beklentisi yüksektir; bu tür ortamlarda veri toplamak çok sıkı onam ve etik denetim gerektirir.'),
  ('Bir anket uygulayıcısı yanıt formunu doldururken katılımcının yanıtını hatırlayamadığı bir soruya kendi tahminini yazıyor. Bu davranış hangi tür hataya yol açar?', 'Görüşmeci kaynaklı ölçme hatası', ['Rastgele örnekleme hatası', 'Kapsam hatası', 'Tabakalama hatası'], 'Anketörün veri uydurması ya da tahminde bulunması ölçümü bozar; bu tür davranışlar eğitim ve saha denetimiyle önlenmeye çalışılır.'),
  ('Bir anket sorusunun ölçmek istediği şeyi gerçekten ölçüp ölçmediğini anlamak için pilot uygulamada uzmanlardan madde madde görüş alınmasına ne ad verilir?', 'Uzman görüşü', ['Kartopu örneklemesi', 'Geri arama (saha) kontrolü', 'Çift veri girişi'], 'Uzman incelemesi, maddelerin konuyu kapsayıp kapsamadığını ve anlaşılır olup olmadığını değerlendirmek için anket geliştirmenin erken aşamasında kullanılır.'),
  ('Bir anket uygulamasında bir anketörün çok hızlı konuşup soruları okurken bazı kelimeleri atladığı fark ediliyor. Bu sorunu saptamanın en etkili yolu nedir?', 'Görüşmelerin bir bölümünü onayla kaydedip dinlemek', ['Anketörün kendi değerlendirmesini sormak', 'Yanıt formlarının renklerini ve kâğıt türlerini karşılaştırmak', 'Örneklem büyüklüğünü artırmak'], 'Ses kayıtlarının dinlenmesi, anketörün soruları standart biçimde okuyup okumadığını doğrudan gösterir.'),
  ('Bir araştırmacının köy kahvesinde yaptığı gözlemde yalnızca erkeklerin bulunduğunu fark edip köyün tüm sakinleri hakkında sonuç çıkarmaması hangi farkındalığı gösterir?', 'Gözlem ortamının belirli bir grubu temsil ettiğinin farkındalığını', ['Gözlemin hiçbir zaman sonuç vermeyeceğinin farkındalığını', 'Köydeki herkesin aynı görüşte olduğunun farkındalığını', 'Gözlemci etkisinin tamamen yok olduğunun farkındalığını'], 'Gözlem yapılan mekân kimlerin orada bulunduğunu belirler; sonuçlar o mekânda bulunan grupla sınırlı tutulmalıdır.'),
  ('Bir araştırma ekibi bir ilçedeki tüm köy okullarının listesini çıkarmış; ancak geçen yıl kapanan üç okulun listede kaldığını fark ediyor. Bu durumda yapılması gereken nedir?', 'Kapanan okulları çerçeveden çıkarıp listeyi güncellemek', ['Kapanan okulları listede bırakıp seçilirlerse yerlerine en yakın okulu koymak', 'Listenin tamamını atıp kolay ulaşılabilir okullarla çalışmak', 'Kapanan okulları örneklem büyüklüğüne ekleyerek hesaplamak'], 'Evrene ait olmayan birimler çerçeveden çıkarılmalıdır; böylece seçim yalnızca gerçek evren birimleri arasından yapılır.'),
  ('Bir öğretmen, öğrencilerin teneffüslerde yalnız kalıp kalmadığını öğrenmek için hem kendisi gözlem yapıyor hem de öğrencilere adsız bir anket uyguluyor. İki kaynağın birlikte kullanılmasının en önemli yararı nedir?', 'Gözlemde görülemeyen duygu ve deneyimlerin ankette ortaya çıkabilmesi', ['Anketin gözlemi tamamen gereksiz kılması ve gözlemin bırakılması', 'İki kaynağın her zaman ve tamamen aynı sonucu vermek zorunda olması', 'Örneklem büyüklüğünün kendiliğinden yarıya inmesi'], 'Gözlem yalnızlığı dışarıdan gösterir; anket ise öğrencinin kendini yalnız hissedip hissetmediği gibi içsel deneyimleri yakalayabilir.'),
  ('Bir araştırmacı bir ankete katılan 500 öğretmenden \'Yeni müfredatı uygulamakta zorlanıyor musunuz?\' sorusuna %60 \'Evet\' yanıtı alıyor. Bu yanıtın hangi tür zorluklardan kaynaklandığını anlamak için en uygun sonraki adım hangisidir?', '\'Evet\' diyen öğretmenlerden bir grupla derinlemesine görüşme yapmak', ['Aynı soruyu aynı öğretmenlere aynı biçimde yeniden sormak', 'Örneklemi 5.000 öğretmene çıkarıp oranı yeniden hesaplamak', 'Soruyu anketten çıkarıp sonucu raporlamamak'], 'Anket ne kadar yaygın olduğunu gösterir; nedenleri ve zorluğun niteliğini anlamak için açıklayıcı nitel görüşmeler uygundur.'),
];
